quests[1429] = { id = 1429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Atal'ai Exile", description = "While you were braving the dangers of the Pool of Tears, one of my scouts returned with a scroll written in blood on dried flesh. It seems to be a judicial sentence against a priest of the Atal'ai tribe.\n\nThis priest was sentenced to a fate worse than death amongst the Atal'ai.\n\nHe was exiled to live far north in the Hinterlands, with the Witherbark trolls.\n\nI will bundle these artifacts. You are to seek out the exile and discover their true use. Return to me once your journey is complete.", progress = "You are brave to come here. Brave or foolish...", completion = "You bring me the summoning artifacts of the Atal'ai?\n\nI see Jammal'an the Prophet is leading the disciples of the Chamber of Blood towards their chosen fate. Has Hakkar returned to the Temple I wonder? Has their fate been met?", objectives = "Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1430] = { id = 1430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Meat", description = "There's a high demand for the succulent taste of crawler meat among my customers; especially the meat from the monstrous crawlers.\n\nIf you plan on heading to the coast, then I could easily make it worth your while to bring me back some of their legs to have transported back to Orgrimmar.\n\nThe coast is to the east from here, and you should have no problem finding the creatures scurrying along the beaches and under the sea.", progress = "I have a cask of wine waiting for your success, {name}. It's only right I taste the goods before I have it shipped back to my customers.", completion = "Ah, this should be perfect. I can't wait to taste these after they are prepared perfectly over an open fire. You should take a sample of it with you on your travels. It truly is delicious.", objectives = "Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1431] = { id = 1431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Relations", description = "Be still, {class}, and allow me to share with you something important to our people, but far from obvious.\n\nWe are a proud race, and the war with the humans tried even Thrall's great patience. You see, our Warchief is wise and prudent, and he continues to put his people first. Ultimately, he is a diplomat, and in his time with the humans he learned much of their ways.\n\nIf the tale I've started piques your interest, then find Keldran near the western exit of the city. His hovel is there.", completion = "Putanni, noble {class}. I am Keldran, student of magic... and other mystical arts.\n\nThe business Craven sent you here to speak to me about requires a touch more subtlety than you've previously needed, but that does not mean you can not still aid our cause.\n\nPlease, make yourself comfortable, and I shall tell you why the Warchief has need of my aid... and yours.\n\nIt starts with appearances, {name}. How the Horde sees itself. How our allies see us. And most importantly, how our enemies see us.", objectives = "Speak to Keldran in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1432] = { id = 1432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Relations", description = "As the Alliance progresses deeper and deeper into Kalimdor, incorrect conclusions may be drawn about the Horde making pacts with the Burning Legion. The Warchief cannot allow that to happen. And with his blessing, I am taking control of overseeing them removed.\n\nI have agents in the area of Desolace at the Ghost Walker Post north of the great Kodo Graveyard. Head south of the Charred Vale in the Stonetalon Mountains and you shall come across it. When you arrive, seek out Takata Steelblade.", completion = "Greetings, {class}. You bring news from Orgrimmar; that is good.\n\nThe demon infestation overwhelms this area even more than the smell of centaur dung. The horse-men claim this land as their own, but clearly there are influences out of their control that will crush them if not kept in check.\n\nIt does not please me that we aid the centaur indirectly, but it is for the good of the Horde, so I do my duty for the Warchief, even if it means helping the warlocks within the Horde.", objectives = "Speak to Takata Steelblade in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1433] = { id = 1433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Relations", description = "The Burning Blade have many agendas, but know that they are evil to their core, their spirits corrupted, and their destruction is the only way to thwart their objectives.\n\nKeldran sent Maurin with me because of his knowledge of the Blade and their warlock ways.\n\nHe has control of our plots against the Blade while I deal with the other demonic threats here in Desolace.\n\nSpeak to him, and he will guide you in his designs.", completion = "Ah, yes. Aid from those loyal to the Warchief is always appreciated.\n\nMy name is Maurin. I am here at the behest of Keldran and the Warchief cub Thrall. It is my desire to aid the youngling leader against the evils that threaten his rule.\n\nCome, come closer, {class}. I shall explain to you my plan for removing the festering boil that is the Burning Blade.", objectives = "Speak to Maurin Bonesplitter in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1434] = { id = 1434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befouled by Satyr", description = "A demon infestation does not occur without other influences--something else allows evil to gain a foothold.\n\nIt may start with a weakened spirit, a needless desire for power; perhaps it's a thirst for revenge, or the appeal for final justice. When we are beset by pain, evil takes advantage of us--evil such as the satyr.\n\nTies have been made between them and the Burning Blade, and Thrall would have them slain. Seek them out to the northeast of here, and return to me when you've driven them back.", progress = "I was warned by a tauren companion that the satyr are not all they appear to be. He believes there is something more to them, that their evil is a twisting of their true nature. But I have not seen such things.\n\nI see only the ruthless slaughter of the weak and the corruption of those who seek dark power.\n\nI will continue in my duty of annihilating them until the Warchief directs me otherwise. Until then, I take no pity on them.", completion = "You have done well, {class}. You have shown honor and dedication.\n\nWhen our campaign in Desolace is done, the Warchief will know that you aided us in our actions here, and that you helped make his will manifest.\n\nI thank you.", objectives = "Slay 7 Hatefury Rogues, 7 Hatefury Felsworn, 7 Hatefury Betrayers, and 7 Hatefury Hellcallers, and return to Takata Steelblade in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1435] = { id = 1435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burning of Spirits", description = "Death is most desirable for those despicable creatures that turn their back on their liege for such selfish reasons. But death is not enough when dealing with those that have given themselves over to the darkness.\n\nTake this gem. When one of the Burning Blade's near death, activate its magic. The spell shall pull the corrupted spirit out of its victim, leaving an infused gem behind.\n\nBring me these infused gems so I may dispose of them properly.\n\nGo now, and may you elude death.", progress = "I have tried to make the magics as simple as possible. Drawing the spirit of your victim out of its injured form should be child's play. Do not rely on the gem's power to slay your foe completely. You must only activate the gem when they are close to death, or it will be useless.", completion = "Ah, you've returned successful. That is good. Give me the gems and I shall put them someplace safe....\n\nMy tasks for you are complete, {class}. Speak to Takata when you are rested. He may have other tasks for you, or perhaps needs you to return to Orgrimmar to inform Keldran of our progress here in Desolace.", objectives = "Return the Burning Gem and 15 Infused Burning Gems to Maurin Bonesplitter in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1436] = { id = 1436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Relations", description = "The fight goes well, {name}. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings.\n\nReturn to Keldran and let him know what we have done. I am sure he will reward you for your efforts here. His cause is important to him, and he will take pride in knowing that the Warchief respects his concerns.", completion = "You have returned from Desolace more than successful, {name}. Thank you.\n\nThank you for your efforts, your time, and your understanding to my plea. Thrall understands and desires peace between the Horde and Alliance, and by taking measures to insure our appearance is acceptable, we will not provoke any further threats of unnecessary violence.\n\nI am indebted to you.", objectives = "Speak to Keldran in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1437] = { id = 1437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vahlarriel's Search", description = "I am Vahlarriel, {name}. I've come here to discover the whereabouts of two missing nobles of a Darnassian merchant family--House Malem. The father of the house fears the worst, and I am to do everything I can to find his missing children. I have yet to start my search for Tyranis or Dalinda, but I am hopeful I shall not be here long.\n\nLast word tells of them passing through the Stonetalon Mountains a few weeks ago.\n\nIf you find their wagon, please, come find me immediately.", completion = "As you rummage around the remains of the wagon, it becomes obvious that it was attacked by both spells and weapons. The battle seemed one-sided and quick; there's no blood to be found, and no remains of any bodies.\n\nWhoever attacked the wagon was efficient and swift.", objectives = "Find and search Tyranis and Dalinda Malem's wagon in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1438] = { id = 1438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vahlarriel's Search", description = "Find both Dalinda and Tyranis if you can and come back to me with your findings. Start your search at this fortress. I will contact my superiors in Darnassus immediately and let them know the situation.\n\n{name}, there is something else I wish to impress upon you. My superiors have shown some concern over Tyranis' and his motives for coming here. It is more important to them that Dalinda is found and brought back safely. Tyranis is to be... gauged before he is taken home.", completion = "Thank Elune someone has finally come to help. Please, {class}, I need your help. My brother Tyranis and I were captured and brought here by the Burning Blade. I think they mean to sacrifice me to their demon masters!\n\n I knew coming to Desolace was a mistake, but Tyranis has recently begun craving knowledge of all things arcane--even against the wishes of our people. He decided to make this trek even after hearing tales of this land's demon infestation.\n\nI fear the worst for him.", objectives = "Find Dalinda Malem in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1439] = { id = 1439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search for Tyranis", description = "We were brought here after the orcs slaughtered all our guards and servants. Oh, the terrible things they did to them! I thought surely they would kill us right there and then, but it became obvious they had other plans.\n\nTyranis attempted to speak to them. I think he wanted to impress them with his knowledge of the arcane... I'm not sure why.\n\nPlease, I can't leave here until I know what's happened to my brother. Find him, then come back for me when his fate is known.", progress = "I fear Tyranis will attempt to learn the Burning Blade's secrets and count himself among their kind if they allow it--he has always adored the power magic brings to those who are seduced by it.\n\nI'm not sure I could endure returning home to my family with news of Tyranis' spirit flirting with such dangers. It's a terrible enough crime among my kind to pursue such things, but to become that which we attempt to protect ourselves from, well, that's apprehensible.", completion = "This is terrible! But I suppose it was necessary. If it wasn't by your hand, it would have surely been by that of my people's. I suppose I should thank you--please forgive me if it doesn't seem sincere. I mean no offense.\n\nWith the knowledge of my brother's fate in hand, it seems the time for my escape has come. If you are still willing, I will accept your aid in escaping this horrible place.\n\nWhen you are ready, we can make our way to safety.", objectives = "Find Tyranis Malem in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1440] = { id = 1440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Vahlarriel", description = "So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family. If you're ready, then there is nothing else for me here--we can leave when you feel the time is right.", completion = "Thank you, {name}. Dalinda made it safely back here to Nijel's Point, and in much better condition than I could have asked for. The fact that she arrived here under her own power was a good sign. I hope you're well?\n\nIt pains me to know that both Tyranis and Dalinda didn't return, but the embarrassment of Tyranis' decisions is hers to endure. It is something she will have to deal with when she returns to Darnassus.", objectives = "Escort Dalinda Malem from Thunder Axe Fortress and then return to Vahlarriel Demonslayer in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1442] = { id = 1442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking the Kor Gem", description = "Greetings, {name}. What can I do for one who follows a holy path?\n\nAh, yes, Stilwell, the blacksmith... from long ago. I remember him well, though, I have not heard his name in some time.\n\nHe never struck me as an impudent man, so I can only assume his desire for a Kor gem is noble.\n\nIf you truly wish for one of the gems, then you must head to the northwest of Ashenvale. You will find Blackfathom Deeps there within some ancient ruins. The naga who still use the gems are down below. Do not go alone, {class}.", progress = "I would be less trustful of one not on a holy path if they came asking about a Kor gem. But I trust your kind more than some of my kin. I do not judge your entire order based on the actions of just one of your fallen kind.", completion = "This is indeed the gem Stilwell desires, but before I can allow you to bring it to him, it must be purified of corruption--the naga wenches imbue the gems with power, that much is true, but of their own, evil kind.\n\nLet Stilwell know that its power is intact, and it should work well for whatever ritual he wishes it to be part of.\n\nI hope you know what you're doing, {class}, this is no simple item you possess.", objectives = "Bring a Kor Gem to Thundris Windweaver in Darkshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1444] = { id = 1444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Fel'Zerul", description = "Jammal'an the Prophet sentenced me to exile from The Temple of Atal'Hakkar. I once felt the high priest was a worthy leader.\n\nHis unyielding faith in his prophecy will bring about the destruction of the Atal'ai. If it hasn't already.\n\nWhen I expressed my concerns, I was labeled an infidel and ousted from the temple.\n\nThose artifacts you brought to me are harmless. But if Jammal'an has found the proper fetish enchantment for the summoning ritual, the world lies in great peril....", completion = "It has been quite some time since we spoke, {class}. I hope your journey was successful.\n\nWhat knowledge did you gain from the exiled Atal'ai in the Hinterlands?", objectives = "Return to Fel'Zerul in Stonard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1445] = { id = 1445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of Atal'Hakkar", description = "So he spoke of Jammal'an's prophecy?\n\nThe Atal'ai spiritual leader believes once Hakkar returns to Azeroth from the Nether, the god will grant the Atal'ai tribe immortality.\n\nFoolish trickery to bring about a premature doomsday if you ask me.\n\nBut you say the exile spoke of enchanted fetishes? This concerns me greatly. If these are in fact the key to the Atal'ai ritual which caused this mess, we must understand their intrinsic powers.\n\nVenture into the Temple, and seize the fetishes!", progress = "If the Atal'ai fetishes hold the power to summon Hakkar and fulfill Jammal'an's prophecy they must be seized. Such powers must be understood by the Horde!", completion = "Brave {class}, you have proven yourself to be a great champion of the Horde.\n\nNow this collection of fetishes of Hakkar must be dealt with at once!", objectives = "Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1446] = { id = 1446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jammal'an the Prophet", description = "My Witherbark companions don't take kindly to strangers around their home.\n\nMe? I don't have a home anymore. I was exiled from my people, the great Atal'ai tribe of the Swamp of Sorrows.\n\nOur spiritual leader, Jammal'an, had what he called a prophecy. He believes the summoning of the god, Hakkar will bring the Atal'ai immortality.\n\nBut I urged caution. What if the prophecy was nothing more than manipulation?\n\nI want revenge for my exile. Bring me Jammal'an's head. Maybe then my people will be free.", progress = "Once Jammal'an has been removed, I stand a chance of returning to my people.\n\nWith Jammal'an as their spiritual leader, the Atal'ai face certain destruction.", completion = "Jammal'an's reckless trust of false visions led my people to their eternal doom.\n\nI thank you, {class}, for avenging my exile. I mourn for my people. I have no home to return to.", objectives = "The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1447] = { id = 1447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Diplomat", description = "Yeah, you're obviously not the smartest {class} to come into Stormwind, but you're about to be one of the dumbest to never leave.\n\nHave you met me friends?", progress = "I didn't mean anything by the comment 'bout you being a stupid {class}. We're friends, right? No hard feelings?", completion = "So, you came to me for a reason. What is it you need?", objectives = "Defeat Dashel Stonefist in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1448] = { id = 1448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of The Temple", description = "There was a time when I was young and full of vigor like you, {class}.\n\nBut now I'm old and unable to explore the world like I once did. Ah, the things I saw!\n\nBut there was one mystery that eluded me. For my final quest, the Explorers' League sent me in search of The Temple of Atal'Hakkar. It was rumored to be located in the Swamp of Sorrows.\n\nBecause of my frail state, I traveled the skies by gryphon in search of it but never found it.\n\nHelp an old dwarf out? Perhaps you will have better luck on foot.", progress = "I have traveled the world from the jungles of Azeroth to the snowy peaks of Khaz Modan.\n\nNever before have I asked for help in my adventures. But my old bones are tired.\n\nNothing would leave me feeling more satisfied than knowing that I completed my final quest for the Explorers' League\n\nIf you'd be so kind as to help me search for the Temple of Atal'Hakkar, {class}, I'd greatly appreciate it.\n\nScour the Swamp of Sorrows and report back with your findings!", completion = "The Temple of Atal'Hakkar has been sunk beneath the Pool of Tears? And surrounded by the green dragonflight?\n\nAn amazing discovery, {class}. But obviously something has gone terribly wrong.", objectives = "Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1449] = { id = 1449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Hinterlands", description = "As I mentioned earlier, I attempted to scout the temple on my own from the air. Well, I wasn't exactly alone.\n\nI traveled to the renowned gryphon aviary at Aerie Peak in The Hinterlands. There I enlisted the aid of one of their finest pilots. The pilot fell off his mount, down into the swamp...\n\nIn my old age the poor fellow's name eludes me. The master of the aviary would remember, no doubt.\n\nJourney there and seek out Falstad Wildhammer.\n\nWe need to find out what happened to that pilot.", completion = "What do you want, laddy? Can't you see I've got problems to take care of here? Who has time to stand around yapping with some {race} chatterbox?\n\nThere are trolls coming out of the woodwork! Make it snappy.", objectives = "Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1450] = { id = 1450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gryphon Master Talonaxe", description = "So you're a glorified errand <boy/girl> for some old Explorers' League geezer, eh?\n\nWell you listen to me, {class}. I don't know who your old buddy was flying around with down in Azeroth. Do I look like Gryphon Master Talonaxe to you? Do I?\n\nIf you're so interested in the flight assignments why don't you ask the gryphon master? If I catch you idling around here for much longer, I'm going to put you to some real work.\n\nNow get a move on.", completion = "Ah, yes. Of course I remember sending one of my gryphon riders to lend a hand to Brohann Caskbelly.\n\nAlways had a soft spot in my heart for the Explorers' League. My father helped with the initial excavation team that discovered Uldaman as a matter of fact.\n\nI sent who I thought was my best gryphon rider at the time with Brohann. He was a chap by the name of Rhapsody Shindigger.\n\nAnd what a gryphon jockey he was! Well until...", objectives = "Speak with Gryphon Master Talonaxe inside the Aerie Peak Aviary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1451] = { id = 1451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhapsody Shindigger", description = "Rhapsody took quite a liking to the booze. Now don't get me wrong -- all of us dwarves up here at the aviary love a good ale when the time is right.\n\nBut ol' Shindigger took to the liquor like a gryphon takes to the skies. And a damned shame it was, too. No one could fly like Rhapsody.\n\nFirst sign of trouble was when he came stumbling back from that mission with your buddy, Brohann. All went down hill quickly after that. Had to let him go.\n\nLast I heard, he's set up a brew camp to the east of here...", completion = "Hiccup!\n\nI'm a-lookin' right at you but you keep bobbing up and down. Makin' me dizzy. Hoho!\n\nHiccup!\n\nWhoa! Did ya feel that? Ground is a-shakin', my friend. I need a drink.\n\nHiccup!", objectives = "Seek out Rhapsody Shindigger in The Hinterlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1452] = { id = 1452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhapsody's Kalimdor Kocktail", description = "Hiccup!\n\nSo that crazy fool Brohann sent ya? My we had quite an adventure...Hiccup!\n\nIf ya want me to tell ya what happened down in the swamp, I'm gonna need me something stiff to drink. It wasn't a pretty scene, ya see. Hiccup!\n\nTell ya what... bring me what I need to whip up a Kalimdor Kocktail and I'll tell ya all about it.\n\nGonna need some Roc gizzards from Tanaris... and let's see... some Groddoc and Ironfur livers from Feralas...\n\nA nice stiff Kalimdor Kocktail... that'll get me talking!", progress = "Ya ever had a Rhapsody Malt? One of my finest brews, if I do say so myself. Hiccup!\n\nBut if I'm gonna relive the horrors of that fateful flight over... hiccup... the swamp, well I'm gonna need me something a wee bit stronger. Hiccup!\n\nDon't suppose you found me those gizzards and livers I need to add that extra kick to my Kalimdor Kocktail?\n\nHiccup!", completion = "I see ya had no trouble at all getting me what I need! Musta been quite a stint you had over there in far-off Kalimdor.\n\nIt won't take but a moment for me to extract what I need from these gizzards and livers. Hiccup!\n\nThen I can distill me a fierce ol' drink and finally tell ya what ya wanna know.\n\nHiccup!\n\nGetting shivers just thinking about that ol' swamp.\n\nHiccup!\n\nLemme whip up a drink real fast.", objectives = "Rhapsody Shindigger in The Hinterlands wants you to bring him 3 Roc Gizzards, 3 Groddoc Livers and 3 Ironfur Livers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1453] = { id = 1453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaimers' Business in Desolace", description = "There's work to be done in Desolace, {name}. It's an atrocious place, befouled by centaur and other nasties. But if you're looking for a good week's honest work, then head there, meet with Kreldig Ungor, and tell him I sentcha.\n\nYou can find him holed up at Nijel's Point--it's a little cozy camp hidden in the mountains of northern Desolace. Just head east if you enter from the Stonetalon Mountains. It's easy to miss, so be on the lookout.", completion = "Glad to see the Reclaimers aren't in short supply of work, or adventurers willing to help out.\n\nI'm Kreldig, {name}. You've made a smart move helpin' out the Reclaimers. Everyone needs something these days: they've lost a family heirloom, a magic item, a loved one. You never can tell. But with the Reclaimers around, there's no reason, for the right price, everyone can't find what they've lost.", objectives = "Speak to Kreldig Ungor in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1454] = { id = 1454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Karnitol Shipwreck", description = "My first order of business is for the mage Karnitol--a noble of some sort in Stormwind. Seems his ship was attacked by sea giants while off the coast in the northwest of Desolace. He and his servants tried to bring one of his more valuable chests ashore, but when the sea giants attacked in droves, he chose to abandon it and teleport himself and his servants to safety.\n\nHe wants us to find the chest and its contents, and return it to him in Stormwind.", completion = "You notice the chest does not seem to have any water damage.\n\nThe second thing you notice is that the top has been forced open, and whatever magical traps were set to safeguard it have long been triggered--this much is obvious from the burn marks around its edges.", objectives = "Find Karnitol's Chest in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1455] = { id = 1455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Karnitol Shipwreck", description = "You take a few moments to figure out what pried the chest open, and you notice along the sides and top of the chest, long, deep scratches that reveal that something other than a man or giant took interest in it. The marks don't appear as if they were caused by dagger or sword.\n\nAfter going through the chest you find it to be completely empty.\n\nNot having another course of action, you close the chest and prepare to leave. Kreldig will be disappointed.", completion = "Welcome back to Nijel's Point, {name}. So, tell me what you found.\n\nWhat!? Nothing? An empty chest ain't gonna get us paid, I'm afraid.\n\nTell me more about these marks you saw... these slashes.", objectives = "Return to Kreldig Ungor in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1456] = { id = 1456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Karnitol Shipwreck", description = "Intriguing.\n\nWell, we might not be without hope quite yet.\n\nAlong that same coast, but to the north near Ranazjar Isle, there're night elf ruins at the bottom of the ocean. A tribe of naga, the Slitherblade, make that their home. I think that'd be our best bet.\n\nIf a scouting party went that far south, then they must've been pretty powerful. If you're gonna find Karnitol's belongings, I'd start with the more powerful naga: the tidehunters or sea witches.", progress = "No offense to whoever Nijel is, but this camp ain't the most comfortable place I've spent a night, if you know what I mean, {name}.", completion = "This is great, {name}! You found Karnitol's belongings!\n\nThose blasted naga, always causing trouble. I think I'd rather spend my life at war with the Horde than have to go against their kind. You've done a great service to the Reclaimers.", objectives = "Find Karnitol's Satchel and return it to Kreldig Ungor in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1457] = { id = 1457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Karnitol Shipwreck", description = "Take Karnitol's things back to Roetten in Ironforge and he'll pay you for a job well done.\n\nHaha, if you're not careful, he's gonna be so pleased with ya that he'll ask you to join us full time.\n\nAgain, great job, {name}.\n\nBe careful on your way back, and don't take too much time--Karnitol's not the most of patient of men, but he's very generous nonetheless.", progress = "Business is booming, {name}, and I don't have a lot of time for questions. If you've got business with the Reclaimers, then let's hear it. If not, I'm gonna have to ask you to talk to one of me underlings--they're adept enough at taking care of things 'round here.", completion = "Ah, the Karnitol business in Desolace. Excellent!\n\nSo, the chest was destroyed, but the items are all here, huh? Well, I'll let him be the judge of that. One good part about this business I got going on here is that if they're not satisfied, I can tell 'em to shove it! They're relyin' on us to find their stuff... not make sure it's all pretty and in good shape when they get it back.\n\nGood work, {name}. Let's see about gettin' you paid.", objectives = "Bring Karnitol's Satchel to Roetten Stonehammer in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1458] = { id = 1458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagents for Reclaimers Inc.", description = "One of my tasks out here involves picking up some reagents for Leftwitch, a gnome mage in Kharanos . Roetten seems to think it's easy coin in the bank since we're out here already. He doesn't really care that we're short-handed as is.\n\nThe first few items on his list should be easy enough to get, and it'd be a good chunk of coin for anyone helping me out.\n\nI need some horns and claws from the Hatefury satyr to the east of here. Bring 'em back to me and we'll get started on the rest of the list.", progress = "Despicable creatures, the satyr. Story says they're somehow tied to the night elves, but I'm not so sure I believe it.\n\nI think they get that on account of that one elf that brought them into the war few years back. World's never been the same since. Lot more dangerous, and a lot scarier.", completion = "Good good, {name}. Not sure if these are of any good quality, but if Leftwitch wanted a specific type, he should have specified before sending the Reclaimers out here to begin with.\n\nWhat say you to getting on with the next item on his list?", objectives = "Bring 10 Hatefury Claws, and 10 Hatefury Horns to Kreldig Ungor in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1459] = { id = 1459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagents for Reclaimers Inc.", description = "Next on Leftwitch's list is... let's see... hmm. Oh, here it is.\n\nSimple enough, but pretty explicit in his directions. He needs venom from the scorpashi, and hide from some kodo. The fine print says both are from specific creatures: the venom's got to come from any of the scorpashi, and the hide's got to come from an aged kodo, not the dying or ancient ones.\n\nMages, I tell ya, some of the stuff they want... it's just weird.", sourceObjective = "Bring 7 vials of Scorpashi Venom and 3 Aged Kodo Hides to Kreldig Ungor in Desolace.", progress = "Sorry I couldn't tell you where to find the kodo or the scorpashi. I'm not terribly familiar with the area, and I haven't had time to explore.", completion = "Your help here's a boon, {name}. You're cutting my time spent here in Desolace by half at least. I'll be back in Ironforge warming my feet in no time with your help.\n\nWhen we get this list taken care of, and I'm back home, look me up, I'll buy you an ale for sure.\n\nBut until then, let's get the rest of these reagents gathered.", sourceObjectiveStatus = "unverified-source-field" }
quests[1462] = { id = 1462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earth Sapta", completion = "Take this and remember, it is sacred.", objectives = "Speak to Seer Ravenfeather for another Earth Sapta.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1463] = { id = 1463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earth Sapta", completion = "I give you one in good faith. You already proved yourself once, but me tinkin' you should be more careful in the future.", objectives = "Speak to Canaga Earthcaller for another Earth Sapta.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1464] = { id = 1464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Sapta", completion = "May fire burn within your heart, {name}.\n\nThe elements await you.", objectives = "Speak to Telf Joolam for another Fire Sapta.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1465] = { id = 1465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vahlarriel's Search", description = "As you continue your search of the wagon you find not only a pendant, but also footprints leading off towards the south. In the distance you can see smoke rising from a large fort. The smoke is from a kept fire, not the burning of buildings, and your instincts tell you that the Malems, if still alive, were taken that direction.\n\nYou think Vahlarriel at Nijel's Point should not only see the pendant you've found, but also know about the signs of life to the south.", completion = "Infuriating! This entire fiasco!\n\nThe two of them were warned about how dangerous coming here would be. Now they're both missing... or worse.\n\nYou said you saw tracks heading to a fort nearby? That may be our best bet.\n\nFrom what the locals have said, that fortress is infested with members of the Burning Blade--orcs who have dedicated themselves to demon causes. They may not represent the majority of the Horde's beliefs, but they are evil and will slay you on sight if you're caught spying.", objectives = "Return the Malem Pendant to Vahlarriel Demonslayer in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1466] = { id = 1466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagents for Reclaimers Inc.", description = "This is the last of the items, and I won't lie, it ain't pretty. I'm also expecting this to take you a little bit longer than the other items.\n\nSo, enough with the warning, let's get this started. Leftwitch says he needs: ten brains from either mana eaters, mage hunters, or ley hunters. Ten nether wings from a nether maiden, sister or sorceress. And... ten vials of doomwarder blood from a doomwarder captain, or lord.\n\nSimple enough, huh? Sheesh... if you wanna pass on this one, I'd understand.", progress = "I didn't even realize these demon things were in Desolace. Last I read, centaur pretty much owned the land after the night elves picked up and left years ago.\n\nI wonder why they took up here, and how.", completion = "Honestly? I wouldn't have thought it. You're amazing, {name}. Taking on demons for a mage's experiments, and coming back in one piece to boot. Great job!\n\nI'm personally gonna tell Roetten about you when I get back to Ironforge.", objectives = "Bring 10 Felhound Brains, 10 Nether Wings, and 10 vials of Doomwarder Blood to Kreldig Ungor in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1467] = { id = 1467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagents for Reclaimers Inc.", description = "To get paid, you're gonna have to get back to Ironforge and speak to Roetten himself. He'll love getting Leftwitch's package out of the way anyway. Just give him this and it should be enough to get your booty.\n\nAnd don't worry, I'm still going to put in a good word for you when I get back. I shouldn't be in Desolace much longer.", progress = "Well met, {name}. Business is booming, the sounds of anvils being struck rings throughout Ironforge, the bellows blow the fires hot, and me wife's making me a pie for dessert after tonight's dinner. Could life be any grander?", completion = "Ah, the package for Leftwitch from Desolace. Excellent. I 'preciate the work, and your timeliness, {class}. Glad to have you aboard for at least this small bit of work.\n\nI got your payment right here. Let it be known that Reclaimers Inc. always pays well for a hard week's work.", objectives = "Bring Leftwitch's Package back to Roetten Stonehammer in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1468] = { id = 1468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children's Week", description = "You're willing to help us here at the orphanage?  Bless you, friend; your aid during Children's Week will be invaluable.\n\nTake this whistle.  You will only be able to use it for a short amount of time - typically not longer than Children's Week itself.  When you use it, you will be able to talk with the child you've agreed to look after.  Using it again will dismiss the child.\n\nBy all means {name} - use the whistle and meet your ward!  I'm sure the child will be most eager to meet you.", sourceObjective = "Use the Human Orphan Whistle to talk with the child you will be looking after during Children's Week.\n\nProvided item:", completion = "Um... hi.  My name is Randis, and I guess you're looking after me?  You're an adventurer, like my mom and dad were.  I'm happy to meet you.\n\nI hope we'll have a lot of fun together.  I have some things I'd like to do, and the matron says you'll be like a big brother to me during this week.  I'd like that a whole bunch, yes sir.", sourceObjectiveStatus = "unverified-source-field" }
quests[1469] = { id = 1469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhapsody's Tale", description = "Before the flight, I drank me a whole keg of stout. Hiccup!\n\nAnd what a flight it was. Zipping around with Brohann following me. Didn't see no temple though. Hiccup!\n\nWell, didn't see no temple till I got a little too tipsy and fell off my mount. I plunged right into the water and was sucked down. Found myself surrounded by a bunch of creepy trolls. Sure swam out of there fast! Even made off with this troll souvenir. Here, take it to Brohann and let him know his temple is down there, indeed. Hiccup!", progress = "At long last you have returned, {name}. It has been quite some time since we last spoke. I thought perhaps you had forgotten about my quest.\n\nDid you locate that wily gryphon rider? Did he have anything to report?", completion = "Rhapsody Shindigger! That's right... how could I forget such a name?\n\nSo he knew about the sinking of the temple all along? Well, that certainly would have saved you some leg work.\n\nBut this Atal'ai artifact! Why, it's quite a find!", objectives = "Bring the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1470] = { id = 1470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piercing the Veil", description = "Greetings, child. I can see that you are still young in the ways of the warlock, power still eluding your grasp. I can sense your eagerness to learn.\n\nAnd you will learn.\n\nThere is no strength in ignorance. Knowledge is our greatest power. Through its application, we can control the chaotic magics and beings of the void, bending them to our will.\n\nI will show you how to bind a servant to your will, but first you must bring me three skulls of the rattlecage skeletons near the abandoned smithy.", progress = "Your power is little now, though I suspect already you sense the possibilities.\n\nEven the dead might feel alive, with that power coursing through us.", completion = "Though you are still untested and young in your learning, you have proven that you possess sufficient ability to master the summoning and binding of an imp. Do not be deceived by an imp's size. Though it lacks physical strength, it possesses powers and a cleverness that will serve you well.\n\nAttend me carefully, {name}, for I will not repeat this lesson, and I will leave its mastery to you.", objectives = "Bring Venya Marthand 3 Rattlecage Skulls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1471] = { id = 1471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "Surely you have seen the circle of summoning below us? Only there will you be able to draw forth an unbound voidwalker.\n\nUsing these runes, you will be able to draw it forth, and then you must dominate it through strength of arms and magic.\n\nWhen it is subdued, it will be indentured to you. Come to me then, and I will elucidate the spell of summoning, so that it may serve you to whatever end you wish.", progress = "I expect to hear of your success, {name}. Not meeting my expectations will be the least of your worries, however, should you fail.", completion = "You have done well, {name}. Now, I will impart to you the spell used for summoning the voidwalker.\n\nThe power that it unleashed upon you is now yours to command. Use it wisely.", objectives = "Using the Runes of Summoning, summon and subdue a voidwalker, then return the Runes of Summoning to Carendin Halgar in the Magic Quarter of the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1472] = { id = 1472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devourer of Souls", description = "A sayaad is a devourer of souls, dominator of wills, tempter of hearts. A creature of profound evil and singular mind.\n\nFolk tales told by righteous and wicked alike use their common name: succubus for females, incubus for males.\n\nThe demon must be lured into our world with a stimulus - the hearts of pure and loving mortals. The sayaad will be unable to resist. Then you can dominate it, and make it your own.\n\nSpeak with my assistant, Godrick Farsan, within the temple. He will help you find your bait.", completion = "You were sent by Carendin? {name}, then.\n\nDo not think light of me because my sight is gone. I see things that lie behind now, with clarity I had never known. What I once thought a curse, is now a boon.", objectives = "Speak with Godrick Farsan in the Temple of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1473] = { id = 1473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature of the Void", description = "It seems the consensus that you are ready to learn to summon a voidwalker.\n\nA being created of the chaos that lies beyond, if you summon one but cannot control it, you will be torn asunder.\n\nThe first voidwalker was summoned by Egalin, and in his grimoire is the process explained.\n\nUnfortunately, it was stolen from us by an agent of the Scarlet Crusade who has it secreted away in his base at a tower to the west. Bring it to me, and I will impart the knowledge to you.", progress = "Egalin was the teacher that taught me. With hardly a look, he was able to command the voidwalker he had summoned.\n\nWhen it came my turn to try, I was overconfident. Do not trifle with the powers that you wield, {name}, they can consume even the vigilant.", completion = "Ah, this is excellent. Like as not, Perrine was ignorant to the true power of the musty book he had stolen from us.\n\nIt will not fall out of our hands again. Observe, {name}, the structure of the spell, the manner in which your power must be channeled.", objectives = "Recover Egalin's Grimoire and bring it to Carendin Halgar in the Temple of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1474] = { id = 1474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "Using these hearts, cast a spell at the summoning circle to open a doorway for the succubus to come through. Your powers are greater now, and you will need all of them to defeat the succubus. \n\nBeware its charms, {name}, many a strong mind has been bound to its will. When overcome, the succubus will be returned to the void, and I will teach you the spell to summon it forth at your command.", progress = "Of the powers from beyond the void, the succubus is one of the most dangerous, as the weak are most easily wrapped around its fingers.\n\nRemember that now and in the future.", completion = "Again, you have done well, {name}. It has been quite some time since I have seen a young {class} with as much potential as you. Be assured that I will continue to watch your progress, and prepare and assist you in your future trials.\n\nFor now, let me show you the summoning spell for your newly dominated succubus.", objectives = "Using the Pure Hearts, summon and subdue a succubus, then return the Pure Hearts to Carendin Halgar in the Magic Quarter of the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1475] = { id = 1475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Temple of Atal'Hakkar", description = "According to legend, The Temple of Atal'Hakkar is a holy shrine dedicated to the ancient god, Hakkar the Soulflayer. Maintained by a vicious tribe of trolls named the Atal'ai, the temple is rumored to be impenetrable.\n\nNow sunk beneath the Pool of Tears, retrieving artifacts from the temple is even more difficult. But that's what I need you to do, {name}.\n\nAid me by gathering the intact Atal'ai Tablets. Bring them to me and I will return to the Explorers' Guild a hero. Together we will share the glory.", progress = "As dusk slowly descends upon my career I turn to you, {name}, to help me in my final quest for the Explorers' League. If my old bones could muster the strength to brave the Swamp of Sorrows and the sunken temple I would be fighting right alongside you.\n\nPride makes it hard for me to ask for your help in collecting the Atal'ai Tablets. But old age forces the necessity.\n\nPlease help me, {name}. I want to retire from the Explorers' League having completed their final bidding.", completion = "The Atal'ai Tablets! Thank you, {name}!\n\nOnce I deliver these to the Explorers' League our names shall go down in history together. You have helped an old dwarf fulfill his final obligation in life. For that I am eternally grateful.", objectives = "Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1476] = { id = 1476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hearts of the Pure", description = "Coaxing a succubus will require the hearts of the pure. But is any mortal without vice?\n\nThrough bits of overheard stories, I found two humans that should do.\n\nThe first is Dalin Forgewright, who has dedicated himself to the care of the Lordaeron refuges, whom are refused by their kin at the Greymane Wall.\n\nThe other is Corma Villard, a woman who remains faithful to her lost love, wandering the Wetlands for a sign of her.\n\nDeliver their hearts to Carendin. But first, let me show you your quarry.", sourceObjective = "Bring the hearts of Dalin Forgewright and Corma Villard to Carendin Halgar in the Temple of the Damned.", progress = "I have been pleasantly surprised by the speed of your progress so far, {name}. Bring me the hearts and you will impress me once again.", completion = "The heart of a goodly man seems much the same as any, when you see it like this, don't you think?\n\nPerhaps we possess something of a... different... view on the subject. These will do, though. I have no doubt that a succubus would be attracted by their purity.", sourceObjectiveStatus = "unverified-source-field" }
quests[1477] = { id = 1477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vital Supplies", description = "Our mages are conducting research at Nethergarde Keep in the Blasted Lands, research vital to our understanding of the Dark Portals. They require nearly constant supplies, but our supply line to Nethergarde is tenuous.\n\nYou must help ensure the supplies make it to Nethergard.  Report to Watchmaster Sorigal in Darkshire, and do as he asks.  This task will take you into hostile lands, {name}.  Prepare yourself.", completion = "Andromath sent you?  Very good.  I have an important task for you...", objectives = "Speak with Watchmaster Sorigal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1478] = { id = 1478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halgar's Summons", description = "Ah, {name}! I just received word from Carendin Halgar that he would like to see you for further training.\n\nYou should be proud of yourself, {name}. It's not every day that Master Halgar personally sees fit to instruct a young warlock.\n\nYou'll be able to find him in the Magic Quarter of the Undercity, near the Temple of the Damned.", completion = "Good, I see Ageron managed to find you, {name}. Let us waste little time with small talk and pleasantries and focus on your training. There is still much you have to learn.", objectives = "Speak with Carendin Halgar in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1479] = { id = 1479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bough of the Eternals", description = "I've heard stories about how the night elves have their bank in a tree - one that looks like a bear!  That's so cool!  Night elves are neat how they like nature and stuff, but bears are just totally awesome!\n\nWould you take me to see the bear-tree in Darnassus, please?  There's a boat that will take us close to there, and it shouldn't take very long.  Please, please, please!", progress = "Are we there yet?", completion = "Wow, it was cooler than I even imagined - the Bough of the Eternals!  I didn't think it'd be so big, but it was!  Did you see the bird on top of it too?!  I wonder how they got the branches to look like that!\n\nThanks for taking me to Darnassus, {name}.  You're awesome!", objectives = "Take the orphan to the bank of Darnassus. The bank itself is hollowed out of a tree known as the Bough of the Eternals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1480] = { id = 1480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corrupter", description = "The torn skin smells rotten, and is remarkably pliable for something that appears to be dry and fragile.\n\nAs you unroll it, you can clearly see the red markings of some kind of language on one side. At the bottom of the skin is a very clear symbol that you guess is a signature of some kind.\n\nPerhaps it is something Maurin could tell you more about?", progress = "The Burning Blade begin to realize how weak they truly are. Their magics are pathetic, their strength feeble.\n\nTheir only power comes from those they serve, and not from any understanding of true power and knowledge.", completion = "Hmm, these runes are indeed a language, {name}, an old language. They seem remotely similar to the Eredun language, but the differences are drastic. If I am not mistaken, this is a contract of some kind.... Here, yes, this symbol is the demon's signature: Lord Azrethoc.", objectives = "Bring the Flayed Demon Skin to Maurin Bonesplitter in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1481] = { id = 1481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corrupter", description = "I believe I can find this demon lord given the proper reagents.\n\nIf he is indeed as powerful as I suspect, I will need items gathered from deadly creatures. But you act in the Warchief's name, so I am sure you will accept my task.\n\nFirst, I will have to break any wards he has against scrying. For this, I will need the scalp from a satyr--but not any satyr. The scalp must come from a Hatefury shadowstalker.\n\nSearch for them among the ancient ruins in the northeast of Desolace.", progress = "Do not bring me an incorrect scalp, {class}. Using the incorrect reagents could cause our deaths. The demon lord may have contingency spells on his person to slay those who would scry upon him.\n\nFate has already dealt me enough pain.", completion = "The shadowstalkers were unable to slay you, {class}. Impressive... most impressive.\n\nThis scalp will do nicely for my spell. While you were away, I was able to gather some of the other reagents needed for the spell.\n\nI am almost ready. I only need a focus for the spell--something to project an image of the demon lord and his whereabouts.", objectives = "Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1482] = { id = 1482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corrupter", description = "An oracle crystal would do nicely. They are crafted by the naga for their oracles to use.\n\nNorthwest of here, along the coast, is a vast coral reef that the naga have taken as their home when this close to the shore. You can find their oracles there. The Slitherblade are deadly and will not react kindly to your intrusions, so be careful and make haste.\n\nWhen you return, we shall see about finding this demon lord Azrethoc.", progress = "I am ready for the oracle crystal, {class}. Finding and destroying this Lord Azrethoc would garner a great deal of favor with the Warchief for both of us. We would do well to work together and to do so swiftly so we may further our own ends and curry favor with the Warchief.", completion = "A precious oracle crystal... flawless... beautiful. Indeed.\n\nWe shall begin immediately. Finding this demon lord should be our primary concern, and its slaying demands our utmost attention.\n\nTake a step back, {class}, and let us see what this demon is, and where he may be found.", objectives = "Bring an Oracle Crystal to Maurin Bonesplitter in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1483] = { id = 1483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziz Fizziks", description = "The Venture Company stole many of the best goblin minds, but from time to time, we get the opportunity to steal some back.\n\nA while ago, the Venture Company outfit in the Stonetalon Mountains hired Gerenzo Wrenchwhistle--a gnome! Their other engineer, Ziz Fizziks, was so taken aback by this, he pleaded with me to find him new employment with the Tinkers' Union. I set him on a few tasks, but he might need help.\n\nMaybe you could look in on him for me? He's stationed at the western edge of Windshear Crag.", completion = "I thought those Venture Company higher-ups were slave drivers, but then I met Sputtervalve, the cruelest of them all!\n\nHa! Though it's better than being out of a job, I suppose... Or worse, working with that Gerenzo. If you're here to help, I've got something for you to do.", objectives = "Speak with Ziz Fizziks in Windshear Crag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1484] = { id = 1484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corrupter", description = "This creature is far more dangerous than I had anticipated.  No doubt Takata questions my abilities to take on such a creature, and it would insult his honor if he were not informed about what just happened.\n\nSpeak to the swordsman, tell him you are willing to slay the demon if he would allow it, but do not press too hard. It is better if he thinks it his own idea.", completion = "I witnessed what just occurred with Maurin and the demon lord. That creature, even as an apparition, seems to have more power than my warlock companion. I wonder if he's up to the task of defeating the monster? It would serve the Warchief better if I go myself, but with my responsibilities here, I would disgrace my clan if I turned my back on my duties here to battle this evil for my own honor.", objectives = "Speak to Takata Steelblade in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1485] = { id = 1485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Familiars", description = "Those warlocks who came before us have earned the distrust of the Horde, and while we are tolerated, we are not loved.\n\nThis has not brought the warlocks closer together, however, as many choose to live reclusively, dabbling in their magics alone. I will not seek to lead you down one path or the other, but only help you in your maturation.\n\nBefore I teach you the art of summoning, bring me six heads of the vile familiars from the cave to the northeast.", progress = "It is important that you can control the beings that you summon through your magic. There are few enough interested in learning the ways of the {class} that I would risk throwing your life away by teaching you something before you are ready.", completion = "Throughout your training as a {class}, you will learn to call forth beings of many sorts. Some may not seem it, but all are useful tools.\n\nDo not be fooled by the imp's small size. As you no doubt noticed, it is still a formidable adversary.", objectives = "Bring 6 Vile Familiar Heads to Ruzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1486] = { id = 1486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deviate Hides", description = "As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.\n\nThese deviate creatures have strange, otherworldly properties. While evil in nature, it is my opinion that some good can come from their existence here in Kalimdor. I believe their hides will be of particular use in the ways of leatherworking.\n\nIf you feel up to the task, venture into the caves below and retrieve some deviate hides.", progress = "I am very interested in examining the hides from the deviate creatures who have infested these caves. Have you had any luck in collecting some, {class}?", completion = "Your efforts shall not go unnoticed in gathering these hides, {name}.\n\nThank you for your dedication.", objectives = "Nalpak in the Wailing Caverns wants 20 Deviate Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1487] = { id = 1487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deviate Eradication", description = "Naralex had a noble goal.\n\nOur great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was. But something went terribly wrong.\n\nNaralex's dream turned into a nightmare and corrupt creatures began to inhabit the caverns.\n\nWhile some Disciples of Naralex seek to awake our master, my concern is with ridding these caves of the evil beasts.\n\nBrave the caverns, {name}, and eradicate the deviate spawn.", progress = "{name}, we, the Disciples of Naralex, need your help. Our numbers are dwindling with our master trapped in his twisted nightmare. We have not the forces necessary to deal with the corrupt creatures which now haunt these caverns.\n\nI beg of you, enter the caves and wage war on the deviate creatures!", completion = "As a Disciple of Naralex, I commend your bravery, {name}.\n\nYour aid in ridding the caverns is the first step in our long plight to see the Barrens restored.\n\nThank you and may you prosper.", objectives = "Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1488] = { id = 1488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corrupter", description = "Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals.\n\nYou have already shown you wish to aid the Warchief, and I would trust you to gather a party to slay the demon lord and his warlock servant.\n\nWhen you are ready, head directly south,  and return to me when the threat has been ended.", progress = "Glory to the Horde, and death to our enemies, {name}!\n\nThe demons in Desolace pose a greater threat than ever before. My hope of returning to the Warchief dwindles as more and more of the foul creatures seem to appear.\n\nI sometimes wish it was only the centaur we had to deal with.", completion = "A mighty victory for us all, {name}. Let us rejoice in your success. I trust now that our future here is not as bleak as I once thought.\n\nThe demons will be slain, the Burning Blade will fail in their efforts, and we may one day have a place we can safely call home again.", objectives = "Slay Lord Azrethoc and Jugkar Grim'rod and return to Takata Steelblade in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1489] = { id = 1489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hamuul Runetotem", description = "The shells you brought me have a taint, one I have never before seen.  I am certain the water of the Oases is the cause, and I can sense the confusion they cause this land.  It is as if the land dreams and cannot awake.\n\nThe Wailing Caverns must be the source of the taint.  But before you go there, speak with Hamuul Runetotem, the elder druid.  I sent word to him of the happenings in the Barrens.  He is wise, and can offer you counsel.\n\nYou will find him in Thunder Bluff, on the Elder Rise.", completion = "I bid you greetings, {name}.  You are welcome here, and I suggest you gather all your strength.  For the task we now set before you ... is a dire one.", objectives = "Speak with Hamuul Runetotem", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1490] = { id = 1490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nara Wildmane", description = "I entered the land of dreams, and dreamed of a cult of druids who dwell in the Wailing Caverns.  I saw that their goals were once noble, but they have lost their way.  They are now servants of the taint seeping through the Barrens.\n\nI am old and my strength fails.  I could not long dwell in that dreaming place and know little more of the tainted druids.  But Nara is young and her spirit is fierce.  She remained in the dreaming when I fled.\n\nSpeak with Nara.  She is in the tent, over yonder.", completion = "Yes, it is true.  I know of the druids in the Wailing Caverns.  I have seen their twisted, scaled faces.  I know their crimes, and I know their plans.\n\nYou must stop them, {name}.", objectives = "Speak with Nara Wildmane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1491] = { id = 1491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smart Drinks", description = "Ok, so the raptor horns didn't work so well.  But that's all right -- no one got rich on their first try!  And besides, I think I found something that'll work even better in my smart drinks!\n\nThere is a substance called Wailing Essence, and I think it is the cause of the strange plants and animals in the Barrens.  Get me some and I'll try it in my drink!\n\nI heard the essence gathers in ectoplasmic creatures in the Wailing Caverns to the west.  Hunt those creatures and gather the essence.", progress = "Where is my wailing essence?", completion = "Great, you got it!  I can't wait to try it out.  This is going to make me a fortune, I just know it!\n\nThank you, {name}.  Take this, and after I'm rich I'll send you more, I promise!", objectives = "Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1492] = { id = 1492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wharfmaster Dizzywig", description = "I have need to send a crate of potions, reagents and other items to my associates in the Old World. Little time I have to actually see them to the dock at Ratchet, and the last caravan has already left.\n\nIf you could, please take this to Wharfmaster Dizzywig. He will ensure that it is placed on the next boat to Blackwater Cove.", progress = "You seek passage on the next ship, or have some item you wish to send aboard it?", completion = "A small enough crate. Yes, I should be able to find room for this aboard the ship. It sails with the next tide, I trust this is soon enough? Excellent. Let me just enter it into my ledger.\n\nAll taken care of! Good day to you, {class}.", objectives = "Bring the Secure Crate to Wharfmaster Dizzywig in Ratchet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1498] = { id = 1498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Defense", description = "As a warrior, one of our most crucial tasks is... protection.  We are the shield of the Horde, and we keep our weaker brethren safe.  If you are to join in our ranks, then you must prove your mettle to me.\n\nGo to Thunder Ridge in Durotar, where live the lightning hides and thunder lizards.  Hunt the beasts!  Show me you are tougher than they!  Brave their assaults and bring me a stack of their singed scales as proof.\n\nDo this, and then I will teach you.", progress = "Do you have the scales, {name}?  Unless you can withstand the attacks of the thunder lizards, you will not benefit from my instruction.", completion = "Ah.  I see you have defeated the thunder lizards, which proves you are tough.  Now I will show you how tough skin and shrewd movements can combine to form an impenetrable wall of defense.\n\nLearn your lesson well, {name}.  And be ready for future instruction.", objectives = "Bring 5 Singed Scales to Uzzek at Far Watch Post in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1499] = { id = 1499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Familiars", description = "Zureetha has been sending novices like yourself to help cull the numbers of the creatures in the cave near where you fought the vile familiars.\n\nI think it would be good for you to gain experience by assisting her. Be sure to tell her that you assisted with the imp problem, she'll probably have a reward for you.", completion = "You have done well, {name}.\n\nAlthough the vile familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead.", objectives = "Speak with Zureetha Fargaze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1500] = { id = 1500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking Naralex" }
quests[1501] = { id = 1501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature of the Void", description = "So few warlocks remain... We risk much, but the risks are warranted. You must quickly reach maturity in your ability if you are to be of use to the Horde and to the Warchief.\n\nIt is time that you learned a new summoning spell.\n\nFirst, you must recover the Tablet of Verga, which was stolen by warlocks of the Burning Blade and is now kept at their lair in Skull Rock to the east of the city. With the tablet, I will show you the runes necessary to summoning a voidwalker.", progress = "Do you have the Tablet of Verga, {name}? If not, I do not wish to speak with you until you do.", completion = "Good. I hope you inflicted some other losses on the Burning Blade when you went to retrieve this.\n\nThey have been a source of great annoyance for the Warchief, and a great blight upon warlocks as a whole.", objectives = "Retrieve the Tablet of Verga for Gan'rul Bloodeye in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1502] = { id = 1502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thun'grim Firegaze", description = "It is vital that a warrior's weapon is one of quality.  And if there is an orc who can craft quality weapons, then that orc is Thun'grim Firegaze.  He is a hermit who dwells atop the hills east of the Crossroads.\n\nIf you seek a weapon, warrior, then you should seek Thun'grim.  To find him, first travel to the Crossroads to the west, then strike east into the hills.  His camp is high on a hilltop.", completion = "My eyes have long dried out from staring into the forge's flame,  but some things I can still see.  I can see you want something.\n\nAnd if you found your way here, then I can guess what you desire.", objectives = "Speak with Thun'grim Firegaze in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1503] = { id = 1503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged Steel", description = "I will give you a weapon, {name}, but first you must aid me.  The Razormanes to the northwest came into my camp a few nights past.  They would not meet me in combat, but they know my eyes are bad--a few distracted me with snorts while others stole from me!  The cowards!\n\nThey took an iron chest, and within it were some forged steel bars.  If you can recover them then I will give you the weapon you seek.\n\nSearch for the iron box within the quilboar camps, and return with the forged steel bars.", progress = "Do you have my steel bars?", completion = "You found them!  And all the bars are here, which doesn't surprise me.  I didn't think the Razormanes would know what to do with fine steel like this.\n\nThank you, {name}.  Here is your reward.  May it serve you well.", objectives = "Bring the Forged Steel Bars to Thun'grim Firegaze in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1504] = { id = 1504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "Now, observe the Tablet of Verga, for it contains the glyphs you will need for the summoning. Take them to the circle in Neeru Fireblade's tent on the other side of the cavern. There you will be able to call for the voidwalker.\n\nYou must defeat it using whatever physical and magical means you have at your disposal. When this is completed, return to me with the glyphs of summoning and I will demonstrate how you may bind the creature to your will.", progress = "The voidwalker is a powerful creature. I remember when it was I that was in your shoes, {name}. Over the years, my own voidwalker has grown to fight me less, though I suspect that is only because it hopes I will let my guard down.\n\nRemember that, {name}.", completion = "You have done well, {name}. I will show you how to summon the voidwalker similar to the one you just defeated.\n\nYou should know that we have high expectations for you, and you have, so far, matched them.\n\nDo not let it go to your head, however, as the tasks that still lie before you will make this seem as simple as waking in the morning.", objectives = "Using the Glyphs of Summoning, summon and subdue a voidwalker, then return the Glyphs of Summoning to Gan'rul Bloodeye in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1505] = { id = 1505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran Uzzek", description = "The Horde honors its warriors because their strength is unquestioned.  But the truly great warriors are great students as well.\n\nSeek out Uzzek.  He is a veteran of many battles and now instructs young warriors in the ways of combat.  You will find him south of Far Watch Post, the orc garrison on the border of the Barrens and Durotar to the east.", completion = "Hello, young one.  Here for some instruction, are you?", objectives = "Speak with Uzzek at Far Watch Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1506] = { id = 1506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gan'rul's Summons", description = "You there. {name}, right?\n\nI hope your schedule isn't busy, because Gan'rul wants to see you right away. You'll find him with the senior warlocks in the Cleft of Shadow.\n\nBased on my past dealings with Gan'rul, your summons is either a very good thing or a very bad thing.", completion = "Good. I was afraid Ophek wouldn't reach you.\n\nIt is time that I further your {class} training. Any business you have currently will have to wait.\n\nI trust there will not be a problem with this?", objectives = "Speak with Gan'rul Bloodeye in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1507] = { id = 1507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devourer of Souls", description = "The time has come for you to learn more of the summoning magics. You will learn to summon a sayaad, a creature of incredible mental powers. It can lull those of weak minds into its servitude--but have no fear! I feel certain that you will be equal to the challenge.\n\nA sayaad can only be summoned when baited with an item that represents great devotion and love. I leave it to you to find such an object.\n\nA suggestion? Speak with Cazul... There seems to be little the ancient warlock does not know.", completion = "Hm... {name}. You are still new to your path, but I sense the possibility for greatness in you.\n\nYou were born with gifts, {name}. See that they do not go to waste.", objectives = "Speak with Cazul in the Cleft of Shadow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1508] = { id = 1508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Cazul", description = "If Gan'rul has sent you to me, it must be that you are to summon a succubus, a female of the sayaad race, and need an object to use for enticement.\n\nHmm... If you trust a blind man to lead you, {name}, then listen. In the bluffs of Orgrimmar, west of the wind rider tower, lives Zankaja. She waits for the return of her mate.\n\nGo to her.", completion = "Have you come with news of Dogran? He was to have returned days ago, and I have heard nothing...", objectives = "Speak with Zankaja in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1509] = { id = 1509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News of Dogran", description = "My mate, Dogran, was recently sent to the Crossroads for duty. It was a promotion, and he was very proud.\n\nI was sad, of course, but I didn't let him know that. And worried, too. The Barrens is a more dangerous place than Orgrimmar, and I feared the worst.\n\nNow it's been a week after he should have returned, and I have received no word from him...\n\nPerhaps you could go to the Crossroads and see if they have any news? He worked with Gazrog, who should still be stationed there.", completion = "Zankaja? That's Dogran's mate, right?\n\nYeah, I've heard from him, but it's not the sort of news we should let get back to her...\n\nNo, he's not dead. But he is injured and a prisoner of the quilboar.", objectives = "Speak with Gazrog at the Crossroads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1510] = { id = 1510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News of Dogran", description = "He was stationed at Camp Taurajo, where we've been trying to weed out the quilboar. He led a few grunts to one of their camps, where he was hurt bad. The others made it back and tried to rescue him. He was in bad shape, his wounds festered, so they were afraid to move him without patching him up first.\n\nThey sent a message here, requesting a healing draught from the trolls at the Malaka'jin at the base of the Stonetalon Mountains. We sent someone to get it, but they haven't returned yet.", completion = "Another orc, eh? I hope you haven't come for the other. He didn't make it. Those goblins did him in good.\n\nHe said he needed a healing draught, but not much else.", objectives = "Speak with Ken'zigla at the Malaka'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1511] = { id = 1511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ken'zigla's Draught", description = "I figured there might be another coming to get the draught, so I prepared it anyways.\n\nHere you go, {name}. Mind you, you should only give half of it to him! That will give him enough strength to move without bleeding himself dry. Wait a night, then give him the other half.\n\nAnyways, you'll want to bring this to Logmar at Camp Taurajo. From what the first one told me, he should have an idea where this Dogran is.", progress = "Yes, what is it?", completion = "Well, it's about time! Dogran has been dying out there, waiting for this.\n\nWe need to get this out to him right away, but most of the grunts stationed here are out on a foraging mission.", objectives = "Bring Ken'zigla's Draught to Grunt Logmar at Camp Taurajo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1512] = { id = 1512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love's Gift", description = "Zankaja is young and beautiful. To be chained to an invalid... I will not allow her to suffer that injustice.\n\nLeave me, {name}. And thank you. I may end my life in glorious battle, instead of a lifeless husk.\n\nAnd please, I would ask you not to tell my mate of this... I do not want guilt on her conscience.", progress = "You have returned. Are you ready to battle a succubus?", completion = "If you tell me that this will suffice, then I trust you, {name}. Allow me to clean it though... Pristine and shining, it may be even more enticing to a succubus.", objectives = "Bring the Dirt-caked Pendant to Gan'rul Bloodeye in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1513] = { id = 1513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "Take this to the summoning circle in Neeru's tent, {name}. Summon forth a foul succubus, then show it your mastery. I believe in the strength of your magic. As always, though, be wary, for pride and overconfidence has overcome many a promising warlock.\n\nWhen you have defeated it, return the pendant to me so that I might deliver the news to Zankaja.", progress = "When I look upon a succubus, my heart begins to soar... But at the same time, I can almost sense my soul's ebb, drifting away like the tides.\n\nBe wary, my friend.", completion = "Success! Be sure I expected nothing less from my star pupil.\n\nYou have proven your worth, and gladly will I show you the method of summoning your subdued succubus. Go now, you have much to learn, and when next I see you, I will expect you to have found true mastery over your succubus.\n\nLeave the sorrow of Dogran and Zankaja to those of us who are longer in years, but remember it, and hold it as protection against the wiles of the dark power you have learned to summon today.", objectives = "Using Dogran's Pendant, summon and subdue a succubus, then return Dogran's Pendant to Gan'rul Bloodeye in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1514] = { id = 1514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Windblossom", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[1515] = { id = 1515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dogran's Captivity", description = "You've made it this far, so if you want to see this through to the end, I won't stop you. I can't spare you any additional manpower though, you'll be on your own.\n\nDogran is being held in a quilboar camp to the north of here. Look for a group of two huts. He'll be heavily guarded--that is, if they haven't killed him yet, or he hasn't succumbed to his wounds.\n\nGood luck.", progress = "Urrrghhhh...", completion = "Foul tasting brew...\n\nI can feel the strength in me now, enough to hobble away... But my leg, I will have lost it for the rest of my life. My arm, too.", objectives = "Bring Ken'zigla's Draught to Dogran in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1516] = { id = 1516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "The time is now, young {class}. You've grown strong and your spirit endures like the earth. Following the shaman's path shows you have wisdom before even proving yourself.\n\nThe element of earth will guide your destiny, becoming part of you if you are ready. But you must stand before the earth itself. If you are ready, then you will see things only shaman know of.\n\nSeek out the Felstalkers to the north, and take from them two of their hooves. Return to me then, and we shall speak more of your future.", progress = "Patience is earth's greatest virtue. The earth witnesses the cycle of all things: the mountains becoming deserts; rivers becoming canyons. The earth is the most stubborn and wise of all the elements and it does not tolerate impatience.\n\nThe earth beckons you now because a time of conflict draws near. When you return to me successful, then you shall be that much closer to being made whole.\n\nOthers will be envious of your wisdom and hate you for their ignorance.", completion = "Excellent. Your success shows that you are prepared.\n\nOf all the elements, earth represents the foundation of all things. It is your strength, your stamina, and your patience. Earth will protect you, but only if shown the proper respect. Like the other elements, even earth can be fickle. Earth is the basis for life, and by observing its laws, you will gain greater wisdom. Never forget the secrets earth shares with you.\n\nI shall make a sapta for you now, and by accepting it, you will realize your path.", objectives = "Bring 2 Felstalker Hooves to Canaga Earthcaller in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1517] = { id = 1517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the strong willed to see the elements as no one else can. Your spirit will be connected to the element the sapta was created for, and only a select few shaman know the recipe.\n\nThe sapta is always drunk in a holy place, and never anywhere else--remember that.\n\nSeek out Spirit Rock southwest of here--it is found at the end of the Hidden Path. Drink your sapta there, and... well, you shall see.", sourceObjective = "Find Spirit Rock and drink the Earth Sapta.\n\nProvided item:", completion = "Ah... {name}... pleased is the earth to have you here.\n\nBound together in body and spirit, you will go forward knowing that the mountains are your strength; the plains, your patience; and the world itself your essence.\n\nStanding before the earth humbly is all that is required of you for you to pass this rite. But the others are not as passive. They may be chaotic and often violent, but such is the nature of the elements. Dual natures opposing one another, you must come to learn these things intricately.", sourceObjectiveStatus = "unverified-source-field" }
quests[1518] = { id = 1518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "Take this rough quartz from me and bring it to Canaga Earthcaller as proof of our meeting. He will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast many others.\n\nBe patient, {name}. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.", progress = "I wish to be the first to welcome you fully to the first of four paths that will forever lead you in your destiny.\n\nIf you have the stone the earth gave to you, I will give you the totem it promised.\n\nIf not, then be gone with you until you have found your way.", completion = "Excellent!\n\nThe totem I will craft for you is more than a symbol of your status among {class}--it has abilities beyond that. One use of the totem is as a focus for spells. Those spells are tied to the earth, and as you earn greater and greater wisdom, more of the earth's abilities will be made accessible to you.\n\nThe trainers will know when you are ready for greater knowledge.\n\nBut for now, take this earth totem...", objectives = "Bring the Rough Quartz to Canaga Earthcaller in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1519] = { id = 1519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "The time has come, young {class}. Your body ages and grows strong, and your spirit endures like the earth. I see it within you-you have wisdom already.\n\nThe earth guides our people, and it speaks to us, as it will to you in time. But you must be tested. If you are ready, then you shall see things only our kind know of.\n\nSeek out the Bristleback shamans in their ravine to the east, and take from them a salve they use in their rituals. Return to me only when you have enough for your own potion.", progress = "The earth is patient, and will wait for you until you are ready because she knows in time all things erode and are reborn. It is the cycle of things. Mountains become deserts. Rivers become canyons. The earth is the most stubborn and wise of all the elements.\n\nYou must learn patience and stamina above all things. The earth calls for you now because she feels you are ready. Consider this your rebirth if you succeed. You will never be able to go back to ignorance afterwards.", completion = "Good, {name}. Your return here signifies that you are indeed prepared for the next step.\n\nOf all the elements, earth represents the foundation of all things. It is your strength, your stamina, and your patience. The Earth Mother will protect you, but only if you show her proper respect. She is the basis for life, and by observing her laws, you will gain a greater wisdom. Never forget the secrets she shares with you.\n\nI shall make your sapta for you now, and by accepting it, a new path will open before you.", objectives = "Bring 2 applications of Ritual Salve to Seer Ravenfeather in Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1520] = { id = 1520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the open minded to see the elements as no one has seen them before. Your spirit will forever be tied to the element the sapta was created for, and only a select few of our kind know the secrets of its creation.\n\nThe sapta is always imbibed in a holy place, and never anywhere else.\n\nSeek out the shaman shrine to the east of here and drink of the sapta.", sourceObjective = "Find Kodo Rock and drink the Earth Sapta.\n\nProvided item:", completion = "Ah... {name}... pleased is the earth to have you here.\n\nBound together in body and spirit, you will go forward knowing that the mountains are your strength; the plains, your patience; and the world itself your essence.\n\nStanding before the earth humbly is all that is required of you for you to pass this rite. But the others are not as passive. They may be chaotic and often violent, but such is the nature of the elements. Dual natures opposing one another, you must come to learn these things intricately.", sourceObjectiveStatus = "unverified-source-field" }
quests[1521] = { id = 1521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "Take this rough quartz from me and bring it to Seer Ravenfeather as proof of our meeting. She will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast mountains.\n\nBe patient, {name}. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.", progress = "Greetings, {name}. You would not return to me if you had not accomplished your task. May I be the first to welcome you fully to the first path of four that will forever rule your travels.\n\nIf you have the stone the earth gave to you, I will give you the totem it promised. If not, then I pity you. There is much pride to be had when you've fully dedicated yourself to the elements.", completion = "Splendid.\n\nThe totem I will craft for you is more than a symbol--it has abilities beyond that. One use of the totem is a focus for spells. Those spells are tied to the earth, and as you earn greater and greater wisdom, more of the earth's abilities will be made accessible to you. Trainers found throughout Kalimdor will know when you are ready for greater knowledge and will let you know as much when you visit them.\n\nBut for now, take this earth totem...", objectives = "Bring the Rough Quartz to Seer Ravenfeather in Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1522] = { id = 1522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "Fire be witcha, mon. I see you be strong in da ways of earth already, an' me tinkin' you be ready to talk to Kranal.\n\nKranal live north of da Crossroads in da Barrens. He be strong in da ways of da elements and can teach ya da ways of fire... if you tink you be ready.\n\nHe be easy ta find, just don' go too far--ya go too far an' ya find yerself in da elves' lands.", completion = "Hmmm, Searn sent you to me, did he?\n\nWell then, Searn could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, {name}. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.", objectives = "Find Kranal Fiss in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1523] = { id = 1523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "Long has it been since you were last tested, {name}. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.", completion = "Hmmm, Xanis sent you to me, did he?\n\nWell then, Xanis could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, {name}. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.", objectives = "Find Kranal Fiss in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1524] = { id = 1524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "You are powerful enough to wield the totem of fire, but that does not mean you are ready.\n\nAlong the Southfury River in Durotar, before the Great Sea, lies a hidden trail to one of the highest peaks in the land. Find your way to the top and you shall find one of our holy shrines watched over by Telf Joolam--the Shrine of the Dormant Flame.\n\nTake this torch to him--it marks that you attempt to tame fire. Return it to me aflame by the brazier at the shrine and I will see you are given the totem of fire.", progress = "Greetin's, {name}. You've found yourself at the Shrine of the Dormant Flame. Only those knowledgeable enough in the shamanistic arts will ever learn the secrets of this place and the power it holds. I'm sorry you made the trip all this way, only to be turned back now--the journey up here is far from safe after all--but I am the keeper of the shrine, and I cannot allow just anyone to wander around here.", completion = "Ah, my mistake, {name}. I apologize. I did not realize you possessed the Torch. I am pleased to make your acquaintance.\n\nMany adventurers find their way here while looking for lost treasure or the promise of mystical creatures to slay, only to be turned away from a seemingly empty shrine. But we know the truth, do we not, {name}?\n\nThis shrine holds a greater secret from the mundane members of the Horde. To us, it is sacred.", objectives = "Bring the Torch of the Dormant Flame to Telf Joolam in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1525] = { id = 1525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "But you did not come here for a history lesson, did you? You came for the Eternal Flame and fire totem.\n\nThe first step is to create a sapta and bind you to the flame.\n\nI can create the fire sapta for you if you bring me two items. The first is fire tar, a simple item usually carried by Razormane spellcasters in eastern Barrens.\n\nThe second item will be more dangerous: a reagent pouch from one of the cultists of the Burning Blade. You can find them in a cave above the ravines northeast of Razor Hill.", progress = "I have enough ingredients for a sapta of fire if you can find the reagent pouch and some fire tar. The Burning Blade fanatics carry the proper components for most of their spells in those pouches, and usually have enough of the items I need that we will not have to search much farther for anything else.\n\nThe saptas are always made from ingredients that are closely tied to their respective elements. It makes our work easier because of the warlocks' ties to fire.", completion = "These will do nicely, {name}.\n\nFire is more than chaos and destruction--do well to remember that. It is also about life, and creation. All things are tied together in such a way. Forces oppose one another, but at the same time, one cannot exist without the other. Both extinguish one another, but also give one another meaning. Always remember this.\n\nUsing different types of magic in conjunction with one another will show not only true skill, but great wisdom.", objectives = "Bring 1 Fire Tar and 1 Reagent Pouch to Telf Joolam in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1526] = { id = 1526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "The fire sapta is finished. The time has come for you to face the flame. Use the sapta at the shrine and head to the top of the mountain to face the manifestation there. He will not attack until you are ready, but he will realize you are able to see him.\n\nStrike him down swiftly, {name}, for he shall only grow in power the longer you take to slay him. Once he is defeated, place his glowing embers within the brazier and light the torch.", progress = "The brazier stands about a third your height, and looks normal, save for the inscriptions along its smooth metal rails. The metal shows no signs of wear from the weather, and the bowl seated at the top of it feels cool to the touch.", completion = "A white hot flame ignites within the bowl as you place the ember within. You can feel the magical effects of the sapta coursing through your body and the fire dances rhythmically before you.\n\nYou place the top of the torch within the basin, and it immediately catches on fire.", objectives = "Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1527] = { id = 1527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "Torch firmly in hand, you turn away from the brazier and look out over Durotar. You feel an excitement tugging at your spirit as the wind picks up and forces the flame to dance violently.\n\nYou start off down the path back to the Barrens in search of Kranal Fiss.", progress = "Yes, {name}? What do you have there?", completion = "Your spirit burns brighter than any torch I've ever seen, {name}, and for that, you should be proud.\n\nIf you continue down this path, the elements will be yours to command, and our brethren will look to you for guidance and wisdom. Let me be the first to congratulate you and present to you your newest totem.", objectives = "Bring the Torch of Eternal Flame to Kranal Fiss in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1528] = { id = 1528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Water be in ya future, mon. I see you be strong in da ways of fire already, an' me tinkin' you be ready to talk to Islen.\n\nIslen live along the coast of da Barrens. If ya head south along the Southfury River, ya canna miss her--look fer da big shark! She be strong in da ways of da elements and can teach ya da ways of water... if you tink you be ready.\n\nShe be easy ta find, just don' go too far south--she be jus' beyond Ratchet.", completion = "The wind approaches you quickly from the horizon; the earth is steady beneath your feet; and your spirit is already warmed by fire--I would say it is time for you to learn about the purity of water.\n\nYour path has led you this far, and your spirit will give you the strength to carry on even further. But the first step is yours to take.", objectives = "Find Islen Waterseer in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1529] = { id = 1529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Long has it been since you were last tested, {name}. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, {name}.", completion = "The wind approaches you quickly from the horizon; the earth is steady beneath your feet; and your spirit is already warmed by fire--I would say it is time for you to learn about the purity of water.\n\nYour path has led you this far, and your spirit will give you the strength to carry on even further. But the first step is yours to take.", objectives = "Find Islen Waterseer in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1530] = { id = 1530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "If there is one lesson you must learn of water, it is this: water means rebirth.\n\nIts power flows, erodes, and makes clean all manner of things. You will find its ability to heal and replenish incomparable, but only when it is pure.\n\nWhen you understand that water, when polluted, can devastate all that it touches, you will appreciate how vital a resource it is.\n\nIf you wish the water sapta, find Brine deep in Southern Barrens. Her home is continually molested by the quilboar there.", completion = "Yes?\n\nMmm, I have a feeling I know what you're going to ask me: what would possess someone to live out here in the deepest part of the Barrens, the threat of quilboar all around, and no protection? Well, we all have our reasons to justify why we act the way we do. The real question is, what brings a lowly {race} to the deepest reaches of the Barrens to speak to a woman who obviously has no concern for her own well-being?\n\nI'm willing to bet we both know the answer to that.", objectives = "Find Brine in Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1531] = { id = 1531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "You be makin' headway now, mon. Your be ready to prove yerself worthy of the air totem, but first, ya must fin' Prate Cloudseer in Thousand Needles. She be willin' ta tell ya how to get yer air totem if ya treat her wit enough respect.\n\nHead south through the Barrens, and after ya reach Thousand Needles, head east. You'll find her hiddin' in a hole wit' her boyfriend--haha, don' tell her I be dissin' her none--she not take it too kindly.", completion = "For the time being, I shall give you what you need to focus your spells and to call upon the spirits of air. Take this totem, and when you are ready, train with me some more.", objectives = "Find Prate Cloudseer in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1532] = { id = 1532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "The winds of Kalimdor rush to meet you and you shall be counted among some of our most powerful <brothers/sisters>. I am proud to see you have come this far and have such a promising future.\n\nThe element of air is a difficult one to control, but I have faith that your skills will overcome any obstacles that are placed in front of you.\n\nHead to the very south of the Barrens, and enter Thousand Needles. It is there, far to the east, that you will find Prate Cloudseer. She will teach you more.", completion = "For the time being, I shall give you what you need to focus your spells and to call upon the spirits of air. Take this totem, and when you are ready, train with me some more.", objectives = "Find Prate Cloudseer in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1534] = { id = 1534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Take this waterskin and head deep into the lush forest the night elves call Ashenvale. It is to the far north of the Barrens.\n\nOnce you've entered the forest, travel west. Along the mountains that separate Stonetalon and Ashenvale, and beyond Lake Mystral, you will find a holy place: the Ruins of Stardust. At the center of the lake you will find a small fountain.\n\nBring me a sample of the fountain's water. It will be the final component you'll need before I send you back to Islen.", progress = "Do you have the water yet, {name}? Tales say the ruins were protected by large creatures of nature that do not care for visitors, but those could be myths to scare off the enemies of the night elves.\n\nRegardless, be careful.", completion = "Wonderful, {name}. With all three samples gathered, I can create for you a vial of the purest water any living creature will find. It will be used in the next steps of your rite of passage.\n\nI am pleased to count you among our kind, {name}. You do all {class} proud, and I look forward to hearing about your exploits in the future.", objectives = "Fill the Empty Blue Waterskin at the Ruins of Stardust in Ashenvale and return to Brine in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1535] = { id = 1535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "To find understanding and gain the sapta from me, you must seek out only the purest forms of water. As you fetch the samples for me, take note of your surroundings. Be aware of the creatures that rely on the water, that protect it. See how it affects forests and deserts. Witness how the very substance that sustains life will force creatures to take lives.\n\nWe shall start with a simple task: down below my hut there is a pond of the precious liquid. Fill this skin with it and return to me.", progress = "I am just about prepared to send you on your other tasks. Have you filled the skin yet?\n\nI know how protective the quilboar can be. Even such a small water source is a vast hoard of wealth to them. They have great feasts when even the slightest rain comes to the Barrens. Water is sacred to their kind because it is so scarce. Do you understand?", completion = "I thought some bloodshed might ensue if you tried to take water from the pool. It is a pity the quilboar do not realize that all living things are tied together; that their greed only perpetuates the pain and suffering of their people. How much could they accomplish if they were to put their differences aside and their clans came together.\n\nAgain, a pity, but more than likely a boon for the other races of the Barrens.", objectives = "Fill the Empty Brown Waterskin at the watering hole below Brine's hut and return it to her in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1536] = { id = 1536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Long ago I followed some companions into the Hillsbrad Foothills. We defended ourselves from some tenacious humans who make their home there and we found ourselves in a small town the Forsaken had taken over: Tarren Mill.\n\nIt was there I found a most peculiar thing: in the center of town was a small well of fresh spring water. I'm not sure the plagued citizens of the town even realize its value--it's a small holy vestige in an unhallowed sea.\n\nBring me a sample of that water in this waterskin.", progress = "The well remaining pure within the town reminds me of stories told to me when I was younger, {name}. Even in times of great pain and sorrow one can find a sliver of hope, a small symbol to rally around. The orc people see Thrall this way. He survived against great odds and rose up to lead our people through his strength and example.\n\nI'm not sure any orc has suffered as much as he has, but at the same time, I'm not sure any orc is as strong as he is either.", completion = "This is good, {name}. You're dedicated to the task at hand and have the ability to seek out that which is needed.\n\nOne more sample is all I need to create the reagent needed for your sapta. Islen will be pleased as well.", objectives = "Fill the Empty Red Waterskin at the well in Tarren Mill and return to Brine in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1558] = { id = 1558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stonewrought Dam", description = "Ironforge is where all the dwarves and gnomes live.  Near there is a place called Loch Modan, and the dwarves built a HUGE dam there.  They say it's one of the biggest things anyone's ever made.  Wow!\n\nCould you take me to Loch Modan and see the dam there, please?  I think it is the Stone... um... Stonewrench Dam?  Stonewrought?  It's big - that's for sure.  I'd like to look out over the big waterfall.  I promise I won't lean over too far!", progress = "Are we there yet?", completion = "WOW - the dam was WAY bigger than I thought!  I could barely hear myself talk from the sound of all the rushing water!  Hey, do you think it would ever run out of water?  Man, what would happen if that dam ever broke!  WOW, that would be scary!\n\nThanks for taking me to see the dam.  That was very kind of you.  I told you I wouldn't lean over too far!", objectives = "Take the orphan to the Stonewrought Dam in Loch Modan. You should take him to the middle of the dam so he can see out over the giant waterfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1559] = { id = 1559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flash Bomb Recipe", sourceObjective = "So you're an engineer, eh?  Well, for your help in getting me those pearls, here's the recipe for flash bombs.\n\nGood luck, and try not to blind yourself!", sourceObjectiveStatus = "unverified-source-field" }
quests[1560] = { id = 1560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tooga's Quest", description = "I am so lost!\n\nMy wife, Torta, sent me out to fetch dinner and I must have taken a wrong turn somewhere.\n\nWould you be so kind as to lead me back to Torta? She's waiting for me just south of Steamwheedle Port.", progress = "Where is Tooga?", completion = "So he couldn't find his way back on his own? Figures.\n\nWell, I guess you deserve something for your troubles....", objectives = "Show Tooga the way back to his wife, Torta.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1578] = { id = 1578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplying the Front", description = "The mountaineers of Loch Modan are fighting troggs, and having a busy time of it!  They need constant supplies of new armor and weapons if we're ever to get a handle on those troggs.\n\nThat's why my colleague Thorvald is there, trying to keep the mountaineers in good gear.  So if you were to make some copper axes and copper chain belts and bring them to Thorvald, he would be obliged.  He might even share his knowledge with you.\n\nThorvald is in Loch Modan's southern guard tower.", progress = "I have no time to chat.  Do you have business with me?", completion = "Ah, apologies!  I didn't realize you were here to help resupply our troops.  The stuff you made will be a big help!\n\nHere are plans for some armor.  I hope you find them useful.", objectives = "Bring 6 Copper Axes and 6 Copper Chain Belts to Thorvald in the southern guard tower of Loch Modan", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1579] = { id = 1579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaffer Jacks", description = "I came to Auberdine because of the quiet.  I want to invent my inventions where it's quiet, because after a night of drinking I don't like all the noise of Ironforge!\n\nSo I took a ship to Auberdine and had a little too much to drink on the way.  I dropped my box of gaffer jacks overboard!  I need my gaffer jacks!\n\nI don't know exactly where I dropped them, but if you fish for them in the ocean you might get lucky...", progress = "Did you find my gaffer jacks, {name}?  Without my gaffer jacks I can't tune my stintle pegs!", completion = "I can't believe you found them!  You must be the luckiest {race} in Kalimdor!", objectives = "Bring 8 Gaffer Jacks to Wizbang Cranktoggle in Auberdine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1580] = { id = 1580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Electropellers", description = "We know you're lucky, but... just how lucky are you, {name}?\n\nOne night I was wandering the roads of Darkshore.  I was looking for a good river or lake to try my new self-propelled, exploding duck decoy and I think I was a little tipsy... because I passed out and awoke hours later in Auberdine.  My hair was singed and my bag of electropellers was gone!  I must have dropped them in the water!\n\nI need those electropellers!  Maybe you can fish them out of some lake or stream in Darkshore...", progress = "Did you find any electropellers?  I'll need them if I'm to continue my research on duck decoys...", completion = "I can't believe it!  You found them!  You are the best fisherman I've ever seen!\n\nThank you, {name}.  And here, take these.  Although you're so good and you probably don't need them, they will help you with your fishing.", objectives = "Bring 12 Electropellers to Wizbang Cranktoggle in Auberdine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1581] = { id = 1581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixirs for the Bladeleafs", description = "Our herb and alchemy shop is booming, but my husband spends so much time mixing potions that we never have time for each other.\n\nCan you help us?\n\nIf you can bring me a supply of pre-made elixirs, then I would be happy to trade with you.  I have some rare herbs that you might find useful.", progress = "Hello, {name}.  Do you have the elixirs to trade?", completion = "These are nicely mixed.  You take great care in your trade, {name}, and that is important for an alchemist.\n\nHere are your herbs, freshly gathered.  May you use them well.", objectives = "Bring 6 Elixirs of Lion's Strength and 2 Elixirs of Minor Defense to Syral Bladeleaf in Dolanaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1582] = { id = 1582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonglow Vest", description = "We in Darnassus, especially we craftsman, are quite busy.  Young adventurers are eager to test themselves in the wilderness, and are in constant need of supplies.\n\nIf you can help me fill my orders of leather goods, then perhaps I can teach you an advanced leatherworking technique.", progress = "Greetings, {name}.", completion = "Yes, these are good pieces. You have a skilled hand and an eye for detail. Your future as a leatherworker is promising.\n\nHere, {name}. Let me show you the pattern to make the Moonglow Vest.", objectives = "Bring 1 Embossed Leather Glove, 5 Embossed Leather Boots and 5 Embossed Leather Cloaks to Lotherias in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1598] = { id = 1598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stolen Tome", description = "You there! {name}, right?\n\nI hope you're sure about becoming a warlock, because if you can't hold your own, you're likely to get pulled under.\n\nI'm to teach you, but I need to make sure you're strong enough first.\n\nThere was a novice studying at the Abbey who ran off to join the Defias Brotherhood. Why do I care? Well, he stole some important books.\n\nOne of those happens to be a book I've wanted for myself, the Powers of the Void. Steal it for me, they have it hidden at their tent in the Vineyards.", progress = "It was too conspicuous for me to steal the book myself. What luck one of their own patsies did the dirty work for me.", completion = "Excellent... I was never able to gain access to this text, it was held in a protected wing of the library that would have looked suspicious for me to be loitering around.\n\nWell, you did a good job in getting this, and I'm convinced that you can probably handle your own imp, so there's no reason for me not to show you how to summon one.", objectives = "Retrieve the Powers of the Void for Drusilla La Salle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1599] = { id = 1599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginnings", description = "You must be the new warlock everyone's been whispering about. Must be someone's taken a liking to you if they've asked me to take time away from my research to start your training.\n\nDon't worry, I won't hold it against you.\n\nThe simplest of the summoning spells you will learn is that of the imp. Before I impart this to you, however, you must prove that you have the necessary magical and physical ability.\n\nBring me three feather charms from the frostmane novices from the cave to the southwest.", progress = "Those feather charms the novices carry have some sort of magical power to them. It will be interesting to research them. I wouldn't have expected it from the trolls.", completion = "Very good, very good! You've done well, {name}. Perhaps the interest that is being shown in you is deserved, after all.\n\nThat'll be for the others to decide--assuming your imp doesn't overpower you and nip your career in the bud. For now, I'm satisfied that you'll probably survive your first few months as a {class}.\n\nA word about the imp, {name}. As a {race} knows, don't let its size fool you, its magic can be very dangerous.", objectives = "Bring 3 Feather Charms to Alamar Grimm in Anvilmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1618] = { id = 1618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gearing Redridge", description = "We dwarves aren't the only ones fighting.  Our human allies have their hands full too!\n\nRedridge is under periodic attack from blackrock orcs, and their supply of equipment is always low.  If you were to help them out, I'm sure their resident blacksmith, Verner Osgood, would teach you a trick or two.", progress = "I hope you're here with good news from Ironforge.  Because I'm at my wit's end!", completion = "Thank you, {name}.  This will help me out tremendously.  With the Blackrock orcs attacking from Stonewatch Keep and the Redridge gnolls lurking in the foothills to the north, I'm always fixing armor and making new weapons for our troops.\n\nThe supplies you brought will give me a moment's peace.  I will have enough time to teach you something...", objectives = "Tormus Deepforge  wants you to bring 4 Runed Copper Belts and 4 Heavy Copper Mauls to Verner Osgood in Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1638] = { id = 1638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Warrior's Training", description = "You've shown yourself to be a competent warrior, {name}.  But you're still young and have a lot to learn.\n\nSpeak with Harry Burlguard--he's usually in the Pig and Whistle tavern, in the Old Town of Stormwind.  Harry is an old veteran and a good teacher.  He can show you a few moves that'll keep you breathing longer.", completion = "Oh ho!  Have a drink with me, lad.  You look tough on the outside, but let's see if your gut can handle a few mugs of the Pig and Whistle's strongest!!\n\nOr... were you here for a lesson?", objectives = "Speak with Harry Burlguard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1639] = { id = 1639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bartleby the Drunk", description = "Yeah, I can teach you.  But first I wanna see what moves you have already.\n\nSee that drunk over there at the end of the bar?  Bartleby?  I want you to get his mug.\n\nHah, and if you know Bartleby then you know he won't just give it to you.", completion = "Hello, fancy boy!  What's a prissy thing like you doing in the Pig and Whistle?  Be careful, or you might break a nail...", objectives = "Speak with Bartleby.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1640] = { id = 1640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beat Bartleby", description = "You want what??  You're crazy!\n\nThe only way you'll get this mug is if you pry it from my cold, dead fingers...", progress = "The only way you'll get this mug is if you pry it from my cold, dead fingers...", completion = "You're a lot tougher than you look!", objectives = "Beat Bartleby, then talk to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1641] = { id = 1641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", sourceObjective = "Here in Stormwind, I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend Azeroth from the Scourge and other threats.\n\nThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a Book of Divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.", sourceObjectiveStatus = "unverified-source-field" }
quests[1642] = { id = 1642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.\n\nAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.\n\nKnow this well, and never forget it.", completion = "Hello again, {name}. How goes your studies of the Tome of Divinity?\n\nThen you should be prepared to have yourself tested. There are always tasks to be done throughout the city and our lands; acts of compassion and understanding; people who need help; creatures to slay.\n\nBy proving you have the patience to help others, especially those who are less fortunate, you prove that you are a servant of the Light and of sound mind.", objectives = "Speak to Duthorian Rall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1643] = { id = 1643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "Your task then, {name}, is to find someone here in Stormwind that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.\n\nDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light.", completion = "Oh, hello, luv. How go your adventures? Oh, I'm so glad to hear you're doing well.\n\nOh, me? Thank you for asking--I'm doing well, all things considered.\n\nThe increase in tradesmen has kind of put a damper on the amount of leather and cloth people are willing to part with these days, so it's been tougher to make clothing for the children at the orphanage, but we'll manage. By \"we\" I mean my husband and I. He's up in Ironforge trying to seek help from the citizens there.", objectives = "Search the Trade District of Stormwind for Stephanie Turner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1644] = { id = 1644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "Bless their hearts, most of them have no families because of the Scourge attacks in the last decade.\n\nMy husband John collects the materials for me to make the shirts and pants for the children, but I haven't even had time to do that. I've been too focused on keeping food on their plates, and a roof over their heads.\n\nWhat's that? You'd be willing to help? Oh, thank the Light, and thank you, {name}.\n\nIf you could bring me some linen cloth so I can sew clothes for the kids, that would help me out so much.", progress = "I hope my John is having better luck in Ironforge. He so dislikes his trips there because it leaves the kids and me alone, but he knows it must be done. He's so kind-hearted.\n\nSome years have been easier than others, but this one's been rougher by far. It's almost as though something in the air is signaling a huge change. Who knows though?", completion = "Thank you, {name}, thank you so much!\n\nThe children will be so pleased, and you've saved me so much time. I'll now be able to focus on the children's other needs, and hopefully my John will be able to return home sooner than we thought.\n\nThank you again, {name}. I knew I could rely on the charity of others. The Light be with you.", objectives = "Bring 10 Linen Cloth to Stephanie Turner in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1645] = { id = 1645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", sourceObjective = "A pleasure to meet you, {name}. I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend Azeroth from the Scourge and other threats.\n\nThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a Book of Divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.", sourceObjectiveStatus = "unverified-source-field" }
quests[1646] = { id = 1646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.\n\nAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.\n\nKnow this well, and never forget it.", completion = "Welcome back, {name}. You've spent time reading the book, I hope?\n\nThen you should be prepared to have yourself tested. There are always tasks to be done throughout the city and our lands; acts of compassion and understanding; people who need help; creatures to slay.\n\nBy proving you have the patience to help others, especially those who are less fortunate, you prove that you are a servant of the Light and of sound mind.", objectives = "Speak to Tiza Battleforge in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1647] = { id = 1647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "Your task then, {name}, is to find someone here in Ironforge that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.\n\nDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light. I will remain here in the temple for your return. Other paladins will need my guidance also.", completion = "THE ORPHANAGE OF STOR... oh, sorry, didn't mean to shout at you, sir,\n\nMy name is John Turner. How are you?\n\nGood, good, glad to hear things go well for you. I've had a long day of work already, and I miss my wife terribly, but that's the price you have to pay when there are mouths to feed and backs to clothe.", objectives = "Search the outer ring of Ironforge for John Turner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1648] = { id = 1648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "My wife and I run an orphanage in Stormwind, mostly for children who have lost parents due to the attacks by the Scourge in the last decade. I come to Ironforge every month or so to see about collecting more supplies from the citizens here, and talk to the various groups to see if they can do anything to help.\n\nThis trip's been agonizingly slow, and not very productive.\n\nIf I could just get some more linen for my wife to make some clothes, I could finally send a shipment home.", progress = "What with the influx of tradesmen here and throughout Azeroth, there's a smaller supply of items we use to make clothes for the children of our orphanage. Helping me collect linen so my wife can make new clothes for them is very noble of you, {name}. Thank you.\n\nHopefully, I'll be able to return home to my wife soon.", completion = "This is so wonderful of you, {name}. Thank you again.\n\nYou're a noble man for doing this for me. It's no wonder you've chosen to follow the Light. I wish there was some way I could repay you for all you've done... what's that? It's the least you could do? See? That's what I'm talking about, {name}, noble to the end.\n\nBe safe, and may the Light protect you in your travels.", objectives = "Bring 10 Linen Cloth to John Turner in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1649] = { id = 1649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Valor", description = "Valor, and all the virtues that go along with it, are like rare minerals: you must cherish them when you find them because of their value, but you must also take time to harvest them... refine them. When mixed together properly, a strong alloy is formed, sometimes unbreakable by even the most powerful blows.\n\nThis strength, your faith, your bravery, must be tested. You must learn to never lose faith and realize that with the power of the Light, you can overcome things that most others cannot.", completion = "Ah, you wish to petition me for a test of valor. Splendid.\n\nThere are many tasks throughout the city and surrounding lands that hold much challenge, and they could use a man with your skills.\n\nThis test should not be taken lightly, {name}. This, like many things along our path, could take our lives. The Church always wishes to bolster its ranks, but it understands the sacrifices needed to ensure the paladins serving it are worthy.\n\nAre you prepared?", objectives = "Speak to Duthorian Rall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1650] = { id = 1650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Valor", description = "Good! Your lack of hesitation is a sure sign that you are prepared and eager to test yourself. So be it.\n\nAt the very ends of Westfall's Longshore, a small house overlooks the ocean. There, a couple lives, the Stilwells. Jordan is an incredible smith, and he's gone to Ironforge to meet with the dwarves for a while. But this has left Daphne, his wife, alone and unprotected.\n\nReports suggest that the Defias have all but taken over the area, Daphne may need some protection from the villains. Go there.", completion = "Hello, {name}. I'm assuming by all that armor and weapon of yours, you're either here to try and take my land, or the Church finally sent someone to help protect me while my Jordan's gone.\n\nWell, let me introduce myself: I'm Daphne Stilwell. It's a pleasure.\n\nNow, you're not too late... I've only killed a half dozen of the scum since last sun up. They've been a little slow getting 'round the bend up there, but they probably saw you coming, which means they'll probably be here any minute.", objectives = "Find Daphne Stilwell in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1651] = { id = 1651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Valor", description = "Now, they'll be coming again soon, I'd wager, so get yourself ready.\n\nI've got myself a gun in the house. I'll grab it and be ready to help you out, but for the most part, you're on your own.\n\nI've no idea how many they'll send, but I'm sure it'll be more than the few they sent earlier.\n\nAsk the Light for whatever blessings you can because... did you hear that? I think they're coming.\n\nWe make our stand near the house!", progress = "We'll make our stand at the house!", completion = "We've done it, {name}! Thank you for your help. You were truly amazing out there. I never thought a {class} could handle so many enemies at once.\n\nYou've truly shown bravery in the face of overwhelming odds.", objectives = "Defend Daphne Stilwell from the Defias attack.\n\nNeither of your spirits must be released from their mortal coils if you wish to succeed.\n\nAfter you are successful, speak to Daphne Stilwell again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1652] = { id = 1652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Valor", description = "Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that.\n\nHe'll send word to Ironforge to let my Jordan know that he has nothing to fear.\n\nOh, how I miss my husband. I can't wait till he returns.", completion = "So, we meet again, {name}, and you are in high spirits, I see.\n\nThe Stilwell home will be safe for another day, and from your story I see that there was no shortage of danger to be found. Well done.\n\nDaphne and Jordan have helped the Church greatly, and having you protect their property--and their very lives--was the least we could do for them.\n\nFor your valor, you will be rewarded.", objectives = "Speak to Duthorian Rall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1653] = { id = 1653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Test of Righteousness", description = "Actually, I have no doubt that Jordan himself would like to thank you, and seeing as I need a messenger to send word that his wife is safe, I think you'd be a perfect choice.\n\nJordan was to be a paladin of the Light before his dedication to his father's craft took him on another path--he's intimately familiar with our way of life and is considered among our most faithful.\n\nHe should still be in Ironforge--he likes to work outside the gates during the day, something about the cool mountain air.", completion = "Good day, {name}. The Light is with you, I trust?\n\nWhat's that? You were sent by Duthorian!? My wife, how is she? I knew there was going to be trouble if I left. Please tell me she's... oh, thank goodness. I'm so glad that she's safe. The Defias were a threat long before these attacks, but now the King's advisors cannot deny it.\n\nWhat else did Duthorian have to say?\n\nYou're the one that was sent to protect my wife? Then I thank you again, {name}. I couldn't think of a better test of valor than that.", objectives = "Speak to Jordan Stilwell in Ironforge", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1654] = { id = 1654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Test of Righteousness", description = "I'd like to reward you if you'd be willing to accept such a thing? Don't misunderstand me, my generosity is dependent on how much help you can be, but I see us both benefiting greatly from such an alliance.\n\nI will craft for you a weapon worthy of what you've accomplished, a symbol of paladinhood and the Light, but you must gather the items I need to craft it. I've already started taking notes on the items, it just requires someone brave and skilled enough to recover them. What do you say, {class}?", progress = "The items you're seeking will be difficult to acquire, but I can assure you, the weapon I will craft for you will be worth the effort.\n\nIt will be my finest work to date, and only a small payment for the service you've done me.", completion = "This is wonderful! You've gotten all the items.\n\nI should have no problem forging you a grand weapon with these. I've actually had the plans for doing this for some time, I just never had the opportunity to gather the goods. Thank you, {name}.\n\nIt feels good to have my father's hammer again... and a Kor gem, I never thought I'd see one of these myself.", objectives = "Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1655] = { id = 1655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bailor's Ore Shipment", description = "Ach, ya startled me, <man/woman>! Can't ya see I was lost in thought?\n\nWhat's that? Jordan's shipment... fer Ironforge. Ahhh, yeah, I know whatcha speak of. Mo'grosh ogres... dat's who took me ol' friend's ore shipment. Caravan was headin' here from the Wetlands and was ambushed. The guard who survived their attack just passed away a few days ago--healer couldn't get to 'em fast enough.\n\nIf you want the shipment, you'll have to head northeast across the Loch. It's got to be there somewhere.", progress = "So, any luck yet? Haha, those ogres didn't get the best of ya yet, did they?", completion = "Yup yup, this is it. Ha! If I'd known you were really gonna head out there and fight some o' them ogres, I woulda given you a list of things to get instead of just this one thing. But, you're not here doin' business for me, are ya?.\n\nA deal's a deal; Jordan wanted a shipment of me alloy, that's what he's gonna get.\n\nTell 'em hello fer me, and be safe, {class}.", objectives = "Bring Jordan's Ore Shipment to Bailor Stonehand in Loch Modan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1656] = { id = 1656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Task Unfinished", description = "{name}, please, I beg of you, can you help me? I have not finished my tasks here on the Mesa--I'm in the middle of my Rite of Strength--and my father asked me to deliver these furs to the inn in Bloodhoof.\n\nI'm far from rested enough to complete both my rite and this task for my father. Would you mind going on for me?\n\nThe inn is pleasant and a perfect place to rest during your long travels. I'm sure you'll agree once you see it.", progress = "Yes, young one? What can Kauth do for you?\n\nThe journey here from the Mesa can be a tremendous burden for some, but a welcome sight for others. Which is it for you, I wonder?", completion = "Ah, the furs I was expecting. Thank you.\n\nThese came faster than I had expected. They will make good blankets for anyone who wishes to stay here.\n\nPlease feel free to stay as long as you like. My inn is always open and all of our people are welcome here. And don't underestimate a good night's rest, it can make a great difference while you're out traveling.", objectives = "Bring the Bundle of Furs to Innkeeper Kauth in Bloodhoof Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1657] = { id = 1657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinking Up Southshore", description = "Celebrate Hallow's End in style... by bringing grief to our enemies in Southshore!\n\nTake one of these specially crafted stink bombs.  It is filled with an odiferous funk that no human - or any weak-willed beast for that matter - can stand to smell.  You'll need to throw it right in the heart of Southshore for it to do its job, so be prepared for a fight against the Alliance!\n\nWhen you've completed this task... this tribute to our liberation, return to me!", completion = "Ah, well done!  I hope the Alliance chokes on the foul gift we've given them, much like we were forced to choke on the yoke of enslavement to the Scourge!\n\nYou've kept the ideas of Hallow's End true, {name}, and for that I salute you.  As an extra bonus, let me share some of these Hallow's End treats I have with you.  I think you might find them to be quite the enjoyable diversion!", objectives = "Toss three Forsaken Stink Bombs into the heart of Southshore in Hillsbrad, and return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1658] = { id = 1658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crashing the Wickerman Festival", description = "I need brave individuals to head up to Tirisfal Glade and check out the Wickerman Festival.  I'm not going to lie - heading up there will be dangerous.  The guards at the festival will be exceptionally vicious.  Still, we need to know how big the festival is this year, and how much trouble the Forsaken are going to cause us during Hallow's End.\n\nIf you're up for it, head to Tirisfal and scout out the festival.  Return to me with the information, and I'll make sure you're well compensated.", progress = "Have you gone up to Tirisfal Glade and checked things out?  They usually hold the festival close to the Undercity...", completion = "Well done, {name}.  The Wickerman Festival will continue to be trouble so long as the abominable Forsaken are allowed to haunt the remnants of Lordaeron.  It is NOT a fitting tribute to that once proud kingdom, let me tell you...\n\nHere's some coin for any repairs you might need, and in the spirit of the season I've also included some treats you might like.  Happy Hallow's End - let's keep it as safe as possible here in Southshore.", objectives = "Locate the Forsaken's Wickerman Festival in Tirisfal Glade. Return to Sergeant Hartman in Southshore once you've done so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1661] = { id = 1661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Nobility", description = "I greet you once again, {name}. I am more proud to call you <brother/sister> than ever before--your dedication is a tribute to us all.\n\nThe time has come for me to bestow a great gift upon you. But know this, for now I give you this freely, but later, when time permits, this will be a much greater challenge to all paladins who choose to undertake my quest.\n\nSpeak to me again and I shall grant you a great boon.", completion = "Congratulations, and may the Light protect you.", objectives = "Speak to Duthorian Rall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1665] = { id = 1665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bartleby's Mug", description = "Ok, here's my mug.  Wait!  Let me finish what's in it first... there we go.", progress = "I saw your fight with Bartleby.  Nicely done!  Did you get his mug?", completion = "There it is!  He sure didn't want to part with it, but you were persuasive.  Well done.\n\nNow for your lesson...", objectives = "Bring Bartleby's Mug to Burlguard", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1666] = { id = 1666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marshal Haggard", description = "You've learned a few moves, but you could still use a decent weapon.  I bet if you spoke with Marshal Haggard he could help you.\n\nMarshal Haggard lives in a manor in Elwynn Forest, at the Eastvale Lumber Camp.  He's retired now but he collected a lot of gear during his career.\n\nLet him know I sent you, and with luck he'll have a spare weapon to offer.", completion = "Who's that?  Burlguard, is that you?  You'll have to step a little closer.  My eyes aren't what they used to be.  Walking up like that, I thought you were a gnoll!", objectives = "Speak with Marshal Haggard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1667] = { id = 1667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead-tooth Jack", description = "Burlguard sent you, did he?  Yes, I have spare weapons around here, but first I have a task for you...\n\nA while ago a Defias villain Dead-tooth Jack tricked me.  It was dark and he was wearing a Stormwind tabard and I thought he was Marshal Dughan.  He said he needed my old Stormwind Marshal's badge and I gave it to him... and then he laughed and ran off before I could catch him!\n\nGet back my badge!  Dead-tooth Jack probably has it stowed in his camp to the south.", progress = "Do you have my badge? I don't want to think of the mischief Dead-tooth Jack could cause with it.", completion = "Great, you found it!  I feared it was gone forever, used by the Defias to impersonate a Stormwind official.  Well that won't happen now, thanks to you.\n\nHere are some weapons I used when I was a Marshal.  I kept them in great shape--take your pick!", objectives = "Retrieve Haggard's Badge from Dead-tooth Jack's camp, and return to Marshal Haggard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1678] = { id = 1678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vejrek", description = "If you want to rise in the ranks of the warriors, then you better be tough.  I can teach you new moves but before that, prove to me you can handle yourself against real foes.\n\nVejrek is the toughest troll you'll find in these parts, and he's who you have to beat.  He has a hut in the foothills just south of Frostmane Hold\n\nBring me Vejrek's head and I'll know you have mettle.", progress = "Have you been to Vejrek's hut, {name}?  Is that troll stink I smell on you?", completion = "Vejrek sure was an ugly one, eh?  Nicely done, {name}!  You have what it takes, now let's start your lesson...\n\nYou may not know it, but a strong defense is very important to a {class}.  It keeps him standing against foes that'd fell others, and that's what your allies need.", objectives = "Bring Vejrek's Head to Muren Stormpike in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1679] = { id = 1679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muren Stormpike", description = "Hello, warrior!  You show a lot of promise, but you still need to learn some tricks and Muren Stormpike is just the dwarf to teach you.\n\nYou can find Muren at the Hall of Arms in the Military Ward of Ironforge.  Talk to him when you're ready to learn what it is to be a warrior.", completion = "Ah, {name}.  I heard the warriors of Dun Morogh bouncing your name around.  I hope you haven't spent all your time in the breweries!", objectives = "Speak with Muren Stormpike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1680] = { id = 1680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tormus Deepforge", description = "Now that you've learned some moves, it's time to get you a decent weapon.  Speak with Tormus Deepforge.  He can make you a weapon I'm sure you'll like.\n\nYou'll find Tormus here in Ironforge, at the Great Forge.", completion = "Muren sent you, did he?  Yes, I can make you a nice weapon... but before I do that, I have a favor to ask of you.\n\nDon't worry.  It's plenty dangerous and could mean your death; it's exactly the sort of job a {class} wants.", objectives = "Speak with Tormus Deepforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1681] = { id = 1681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironband's Compound", description = "My mentor, Sturgy Ironband, had a compound south of Helm's Bed Lake in eastern Dun Morogh.  There he taught blacksmithing and he was the best.\n\nBut one day, one of his students brought him a load of strange ore.  Master Ironband called it umbral ore and was eager to work with it, but soon after it arrived... a band of Dark Iron dwarves attacked his compound.  They killed everyone!\n\nEnter Ironband's compound, {name}, and avenge my master's death.  And bring me the load of umbral ore that caused it.", progress = "Have you entered Ironband's Compound?  Did you find the umbral ore?", completion = "You found it! Well done!\n\nI hope you killed a host of Dark Iron dwarves while searching.  I fear that Ironband's compound won't be the last place we see them.\n\nBut thank you for the ore, {name}.  I'm eager to work it and find its properties.", objectives = "Bring a load of Umbral Ore to Tormus Deepforge in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1682] = { id = 1682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grey Iron Weapons", sourceObjective = "Here are some weapons, hot off the anvil and made with the new umbral ore you brought me!\n\nPlease, {name}, take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[1683] = { id = 1683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorlus Vilehoof", description = "Before I can teach you, you must show me your resolve.\n\nThe satyr Vorlus Vilehoof has found one of our remote moonwells, southeast of the Ban'ethil Barrow Den.  He now splashes within it, defiling its pure waters with his filth.\n\nFind Vorlus at the moonwell and destroy him.  Bring me his horn as proof and I will begin your advanced training as a warrior.\n\nThe path to the moonwell is hidden well, {name}, but stay focused and alert and you will find it.", progress = "Do you have the horn, {name}?  Is our moonwell free of the fiend Vorlus?", completion = "Well done, {name}.  It is good to know Vorlus is defeated and our moonwell cleansed, and it is good to see young warriors eager to keep our beloved Teldrassil free of corruption.\n\nNow let us begin your training...", objectives = "Bring the Horn of Vorlus to Elanaria in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1684] = { id = 1684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elanaria", description = "Greetings, warrior.  Your skill grows, but there is more to your profession than you may believe.  To further progress, you must soon find a teacher.\n\nThe warrior Elanaria dwells in Darnassus, at the Warrior's Terrace.  She can instruct you.", completion = "I bid you greetings, {name}.  Your name rings loudly in Darnassus, for you show promise.  But we shall soon see if you possess the strength of will to follow the path of the {class}.", objectives = "Speak with Elanaria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1685] = { id = 1685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gakin's Summons", description = "Isn't that how it always works? Was looking for you all day and couldn't find you, now when I'm not expecting it, you come and walk right up to me.\n\nI've wasted enough time trying to find you, so I won't delay you any longer. Master Gakin's summoned you for additional training. Seems to me you should seek him out as soon as possible.\n\nYou'll find him in the basement of the Slaughtered Lamb tavern. By the way, you might want to keep that particular location quiet. Don't want word spreading about it.", completion = "About time you showed up. Though, perhaps I should have sent someone more capable than Remen to find you.\n\nNo matter.\n\nYou've gone too long without training, and a {class} without training isn't like to keep his head on his shoulders for long.", objectives = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1686] = { id = 1686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shade of Elura", description = "You have learned much, {name}.  Now we will craft you a weapon.  A warrior's weapon.\n\nTo do this, you must travel to Darkshore.\n\nLong ago a ship crashed upon the rocks near the Auberdine lighthouse, scattering many crates of elunite ore along the ocean floor.\n\nFirst, you must defeat the elunite's guardian, the Shade of Elura.  Once the ship's captain, she cursed herself to roam the deeps and protect her shipment for all time.  Defeat her, gain her medallion, and gather the crates of lost Elunite.", progress = "Have you defeated the Shade of Elura, {name}?  And do you have the lost elunite ore?", completion = "Bravely done, {name}.\n\nYou have given the Shade of Elura much deserved peace, and we will use the gathered elunite to make a fine weapon for you.", objectives = "Bring 8 loads of Elunite Ore and the Medallion of Elura to Elanaria in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1687] = { id = 1687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spooky Lighthouse", description = "Sometimes late at night, our matrons at the orphanage will tell us spooky stories.  Those RULE!  There's one about a ghost that haunts a lighthouse in Westfall.  They say he was a pirate captain who had his ship taken from him by other pirates.  Wow!\n\nCould you please take me to the lighthouse in Westfall?  I wanna see if the ghost of that captain is there!  I promise to stay close to you; I won't run off or anything!", progress = "Are we there yet?", completion = "WOW, that was a real life ghost!  That was so awesome - I can't wait to tell everyone back at the orphanage.  Captain Grayson... he even looked like a pirate!  When I grow up I wanna be a ghost pirate too!\n\nThanks for taking me to Westfall, {name}.  I know there are scary things out there in the wilds of Westfall, and I hope I wasn't too much of a pain.  You're awesome!", objectives = "Take the orphan to see the lighthouse off the coast of Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1688] = { id = 1688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surena Caledon", description = "I had a student named Surena Caledon. She stood where you stand now, eager to learn of warlock magic, and possessing no small bit of talent. More than that she was young and pleasing to the eye. Had I seen it then, the traitorous trollop!\n\nThe thieving wench ran off with one of the Defias, Erlan Drudgemoor. While her loss is of little importance, I gifted her a bloodstone choker that I must have.\n\nHer life means nothing to me now. You will find her at the Brackwell Pumpkin Patch. Retrieve what is mine.", progress = "Even the older and wiser can be unmanned by the wiles of youth and beauty, {name}. A piece of advice you would do well to remember throughout your life.", completion = "Surena was talented, but not enough so to gain mastery of {class} magic on her own. It's a shame to see talent wasted, but sometimes it is necessary.\n\nI hope my investment in you will bear different results.", objectives = "Retrieve Surena's Choker for Gakin the Darkbinder in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1689] = { id = 1689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "By retrieving my choker and besting Surena, you've proven that you're at least as capable as she was.\n\nWith that said, I can tell you're direly in need of training. You can manage the flows of magic, yes, but being a warlock is much more than that.\n\nI will show you how to command a voidwalker, but before I can, you must call one forth at a summoning circle and subdue it using whatever weapons--physical and magical--you have at your disposal. Use the magic of this choker at the summoning circle below.", progress = "I cannot show you how to control a voidwalker until you have overtaken one.", completion = "You did better than I expected, {name}, but as well as I'd hoped. Now, you can learn to command your subjugated voidwalker, an ally you will find valuable in the trials that are sure to stand before you.\n\nI have nothing more to teach you at the present, but I am far from done with you, {name}.", objectives = "Using the Bloodstone Choker, summon and subdue a voidwalker, then return the Bloodstone Choker to Gakin the Darkbinder in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1690] = { id = 1690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wastewander Justice", description = "You there!  It's time for you to be a big helper to the Gadgetzan Water Company.\n\nThe Wastewander nomads out in the Tanaris desert have seized almost all the water wells!  Without access to them, our water supply will dry up in no time.  If you want to get in our good graces, then you'll help us bring justice to those nomads!\n\nHead east of here and bring down ten Wastewander Bandits and Thieves, then report back to me on the double.  Justice waits for no man... goblin... bah, just get on it!", progress = "Back so soon?  I hope you were able to bring some goblin-style justice to those Wastewander Bandits and Thieves like I asked you to!", completion = "Now that's what I call efficiency!  You've helped thin out the nomad's numbers enough now that we can start to think about how we can win back those water wells.\n\nThe Gadgetzan Water Company thanks you for your help, but we're far from done in dealing with those foul nomads.  Listen close - here's what we need next...", objectives = "Take down 10 Wastewander Bandits and Thieves east of Gadgetzan, then report back to Chief Engineer Bilgewhizzle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1691] = { id = 1691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Wastewander Justice", description = "We need you to take on the stronger ranks of the Wastewander nomads now.  You've done a good job thus far, but if we are to take back those water wells, then it only makes sense to do it against as few nomads as possible!\n\nThis time around we need you to take down their rogues, assassins, and shadow mages.  You'll find them east and southeast of here.\n\nI'm not going to lie to you - they're a nasty lot.  Do this for us though, and we'll be on our way to taking back what is rightfully ours!", progress = "Well, were you able to take out those nomads like I asked?  The Gadgetzan Water Company is developing plans based on your success here!  Don't let us down, now...", completion = "Top notch work, {name}... top notch!  You've thinned down the nomad population to a point where we can actually take the fight to them!\n\nIf you haven't already, talk to Spigot Operator Luglunket here; he gives a bounty on any of the Wastewander water pouches you may have run across while bringing those nomads to justice!", objectives = "Take down 10 Wastewander Shadow Mages, 8 Wastewander Rogues, and 6 Wastewander Assassins for Chief Engineer Bilgewhizzle in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1692] = { id = 1692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smith Mathiel", description = "I have placed the elunite you gathered into a case.  Take it to the blacksmith Mathiel, and he will craft for you an elunite weapon.\n\nMathiel is to the south, on the other side of this building.", progress = "Greetings, young {class}.  How might my skills serve you?", completion = "Ah, elunite ore.  This is a fine metal to work with, for it is blessed by the goddess Elune herself.  It would be an honor to craft weapons with it.\n\nPlease wait while I work...", objectives = "Bring the Case of Elunite to Smith Mathiel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1693] = { id = 1693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Elunite", sourceObjective = "{name}, I have crafted these weapons with the elunite you brought to me.  Please, take whichever most suits you.\n\nAnd I must thank you.  Working with elunite is both an honor and a pleasure.", sourceObjectiveStatus = "unverified-source-field" }
quests[1698] = { id = 1698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yorus Barleybrew", description = "Yorus Barleybrew has issued a challenge to all able warriors of the Alliance.  He waits at the Lakeshire Inn, in Redridge, and pledges a grand reward to anyone able to pass his trial.", completion = "Hah!  So you heard of my challenge, did you?\n\nWell sit down and listen.  Have a drink, and savor it... because it might be your last.", objectives = "Speak with Yorus Barleybrew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1699] = { id = 1699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rethban Gauntlet", description = "I call my challenge the Rethban Gauntlet.  To pass the trial, all you must do is enter the Rethban Caverns, to the first fork, then return here.  Easy!  Except there are a few wrinkles...\n\nYou have to return within an hour.\n\nThere are whole heaps of Redridge Gnolls in the way.\n\nBefore you start, you have to take a swig of my family's signature drink: Barleybrew Scalder!\n\nSo what do you say?  The Rethban Caverns are in the foothills north of Lakeshire.  Are you ready to run the Rethban Gauntlet?", progress = "Time is wasting, {name}.  If I were you, I'd get going...", completion = "You made it!  Well done!  Three cheers for {name}!", objectives = "Enter the Rethban Caverns, reach the first fork, and return to Yorus Barleybrew within the time allowed.\n\nYou must not die and release your spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1700] = { id = 1700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimand Elmore", description = "I made a copy of my notes on the techniques I learned while making your armor, and I need them sent to Grimand Elmore.  He's here in the Dwarven District, in the weapon shop.\n\nAnd duck when you give these to him.  He's fiercely proud of his skills, and won't like the idea of learning something from me...", progress = "Hello, and well met.  How might I be of service to you?", completion = "Furen wrote this?  How dare he!  Why, I taught him everything he knows!  To think he could teach me something is outrageous!  Outrageous!\n\nHm... but there is something in his notes that I'd like to try...", objectives = "Bring Furen's Notes to Grimand Elmore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1701] = { id = 1701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Hardened Mail", description = "So I gave you a nice shield, but we don't have to stop there.  I know the secrets to make extremely hard mail armor.  It's not easy and it takes very rare materials, but if you're willing to do the legwork then I'll make a piece for you.\n\nWhat do you say, {name}?  If you're up for the challenge, then I'll give you a list of what to get and where to get them.", progress = "How goes the scavenger hunt, {name}?  Do you have the materials?", completion = "You got it all?  Amazing!  I was afraid those chimaeras would eat you up for sure!\n\nWell let's get started on that armor...", objectives = "Gather the materials Furen Longbeard requires, and bring them to him in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1702] = { id = 1702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shieldsmith", description = "You really showed what you were made of when you ran the Rethban Gauntlet, {name}.  And I'm true to my word.  I'll get you the reward I promised...\n\nExcept it's in Stormwind.\n\nTalk to my friend, Furen Longbeard, in the Dwarven District of Stormwind.  He's the best shieldsmith you'll ever meet, and he owes me a big favor.\n\nHere, take Furen this cask of Barleybrew Scalder and ask him for a shield.  He'll give you a nice one.", progress = "Hello!  Dry times, don't you think?", completion = "Ah, Barleybrew Scalder.  Great stuff!  So you've been to see Yorus, eh?\n\nI can get you a shield, yes sir!  You won't find a better one, and that's no lying!", objectives = "Bring the Cask of Scalder to Furen Longbeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1703] = { id = 1703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathiel", description = "I made a copy of my notes on the techniques I learned while making your armor, and need them sent to the blacksmith Mathiel.  He lives in Darnassus which is quite a long way off, but I'm sure he'll be very grateful to learn what I've learned.", progress = "I bid you greetings, {class}.", completion = "These are interesting, very interesting indeed.  My dwarven colleague Furen has made quite a grand discovery!\n\nThank you, {name}.  It will be an honor to apply his new techniques to my own craftings.", objectives = "Bring Furen's Notes to Mathiel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1704] = { id = 1704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klockmort Spannerspan", description = "I made a copy of my notes on the techniques I learned while making your armor, and need someone to take them to Klockmort Spannerspan.  He's a gnomish blacksmith in Ironforge and when he learns what I've learned... I bet he'll pull off his own beard in excitement.", progress = "Good day, or morning or evening.  I can't tell from way down here.  So do you have business for me?", completion = "Oh my!  These notes are amazing!  And what's more... they're incredible and they're stupendous and they make my knees go all a-wobbly!\n\nFuren had a breakthrough!  A real breakthrough!  I can't wait to try out his new technique!", objectives = "Bring Furen's Notes to Klockmort Spannerspan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1705] = { id = 1705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Blood", description = "I hate to admit that Furen might have really found something.  But to be sure I'll need to try his techniques on a new piece of armor.  If you help me with the materials, {name}, then you can have the armor.\n\nTo make this armor, I need samples of burning blood and a burning rock.\n\nThe only place I know to get them is Duskwood.  The Nightbane worgen based in the Roland's Doom mine have burning blood, and their leader Gutspill will have the rock.\n\nMay fortune grant you speed, {name}.", progress = "{name}, do you have the burning blood and rock?  I'll need them to complete the armor.", completion = "Nice work!  Now if you'll excuse me, I have some work to do myself...", objectives = "Bring 20 vials of Burning Blood and 1 Burning Rock to Grimand Elmore in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1706] = { id = 1706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimand's Armor", sourceObjective = "I can barely believe it!  Furen's technique was a success, and this armor should withstand tremendous levels of stress.\n\nHere you are, {name}.  And thank you.  I wouldn't have believed Furen's discovery if you hadn't gathered the materials I needed to test it myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[1707] = { id = 1707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water Pouch Bounty", description = "Greetings {name} - the name's Luglunket, and we've got an important job for you if you're up for it!  Huzzah!\n\nNothing would please me more as a seasoned spigot operator to take any Wastewander water pouches you might find out in the desert.  That's our water anyway - the nomads have just stolen it is all!  The Gadgetzan Water Company will offer you an official care package for every five you turn in.  Most importantly though, you're helping Gadgetzan help itself!", progress = "Got the five Wastewander water pouches we need?  If you do, then the Gadgetzan Water Company Care Package, Model 103-XB, will be yours!", completion = "Excellent - the more water pouches we are able to reclaim, the further away from disaster we'll all be!  Keep 'em coming, and I will be sure to reward you for every five water pouches you bring me.", objectives = "Bring 5 Wastewander Water Pouches to Spigot Operator Luglunket in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1708] = { id = 1708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Coral", description = "I want to try Furen Longbeard's new techniques on my own piece of armor.  And because you helped Furen and he helped me, you're welcome to the armor after I make it!\n\nTo finish the piece, I need a special coral, searing coral.  It grows in only one place--along the coast south of Menethil Harbor in the Wetlands.\n\nBring me enough searing coral and I'll get right to work on the armor.  And hurry, {name}.  I'm so eager to get started it's making my toes twist!", progress = "Hello hello, {name}!  Do you have the searing coral?  I can't wait to get to work!", completion = "That's the stuff!  Well done!  Now let me get this smelted and hammered so I can apply Furen's technique with my own and then we can see what happens!\n\nOh my, oh my!  I just know the armor will be very very very tough!", objectives = "Bring 20 loads of Searing Coral to Klockmort Spannerspan in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1709] = { id = 1709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klockmort's Creation", sourceObjective = "Here's your armor, {name}.  Furen's process worked brilliantly!  Perfectly!  Marvelously, truly!\n\nYou could run this armor over with a siege engine and it would spring right back into shape!", sourceObjectiveStatus = "unverified-source-field" }
quests[1710] = { id = 1710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunscorched Shells", description = "My colleague, Furen Longbeard, made a discovery which I am eager to test.  I wish to try it on a new armor that I am researching, for I believe Furen's techniques will produce superior results.\n\nWill you help me?  If you gather what I need to make the armor, then I will make an extra piece for you.\n\nI need the sunscorched egg shells of the Highperch Wyverns who dwell at Highperch, in Thousand Needles.  Search for the shells below their nests, and return to me when you have a sufficient amount.", progress = "Do you have the shells, {name}?  They are quite strong, and can be rendered into a lacquer I will use to coat the links of my new mail armor.", completion = "Ah, thank you.  These will work splendidly!\n\nI will begin fashioning the armor immediately...", objectives = "Bring 20 Sunscorched Shells to Mathiel in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1711] = { id = 1711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathiel's Armor", sourceObjective = "I have finished with your piece of armor, and I am quite pleased.  Furen's new techniques meshed perfectly with my own and I am sure this armor will prove to be quite resilient.\n\nThank you, {name}.  And may this serve you well in future battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[1712] = { id = 1712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cyclonian", description = "I have spent ages watching this site.  I watch, so that one day I might see the great Cyclonian fall.  But I have not yet found a champion to defeat the wind lord.\n\nPerhaps you are that champion.\n\nProve it to me.  Gather the items I need to summon Cyclonian, and I will know you are a great warrior.  Perhaps then you can defeat him and gain his whirlwind heart.\n\nIf so, then I will infuse the heart's power in a weapon, and I will give that weapon to you.\n\nHere is a parchment with the items I need.", progress = "Do you have the items, {name}?  Gathering them is the proof I need that you have the strength to face Cyclonian.", completion = "You have gathered the items for my spell, and have shown me your strength and cunning.  But the next stage of our quest is even more perilous.\n\nLet us hope your strength does not falter.", objectives = "Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1713] = { id = 1713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Summoning", description = "I am ready to perform the ritual to summon Cyclonian.  When he is summoned, you must defeat him and take his whirlwind heart.  This I will use to instill a weapon with Cyclonian's power.\n\n{name}, are you ready to face the wind lord?", progress = "{name}, I must have the whirlwind heart!", completion = "You did it!  You defeated Cyclonian and gained the Whirlwind Heart!", objectives = "Bring the Whirlwind Heart to Bath'rah Windwatcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1714] = { id = 1714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of the Exile", progress = "The cauldron bubbles.  Its vapors beckon...", completion = "The charms sink slowly into the cauldron's depths...\n\nA large bubble rises to the surface of the liquid and breaks...\n\n...And a churning lump of molten rock is revealed." }
quests[1715] = { id = 1715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slaughtered Lamb", description = "Hmph. Times past, all warlocks in Khaz Modan were trained under the auspices of the masters of Gnomeregan, but now that we've all been forced to relocate into this rat's hole in Ironforge, and Magni's decided to keep a careful watch on us, we're forced to send our novices to Stormwind for training.\n\nLuckily, Gakin's no slouch, so you'll still learn what you need to know, but it burns my blood!\n\nAnyways, you'll find Gakin in the basement of the Slaughtered Lamb in Stormwind.", completion = "Sent by Blackwrench, were you? Damn warlocks in Ironforge need to get things sorted out. There's only so much room and so many teachers in Stormwind. With all the increased traffic, we're sure to attract attention sooner or later.", objectives = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1716] = { id = 1716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devourer of Souls", description = "A sayaad is a devourer of souls, dominator of wills, and tempter of hearts. It knows nothing but evil.\n\nSalacious tales refer to the demon by its common name: succubus for females, incubus for males.\n\nA stimulus is required to beckon the creature. With a symbol of love as bait, it will surely answer your call. Defeat it, and make it your tool.\n\nIt will be hard to find a thing of this nature, though. You should speak with Takar the Seer. You will find him in the Barrens of Kalimdor near Camp Taurajo.", completion = "Was your crossing difficult, {name}? You have come a long way to speak with me. But fear not, I know why Gakin has sent you, and he was wise to, for I can help you in your search.", objectives = "Speak with Takar the Seer in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1717] = { id = 1717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gakin's Summons", description = "{name}! Didn't expect to see you around these parts, but I was instructed to keep an eye out for you.\n\nIt's past time you got some more training, so you should stop in to see Gakin the next time you're in Stormwind. He'll be waiting for you.", completion = "I'm glad someone was able to get a hold of you, {name}. I was beginning to fear the worst. It would be a shame to lose you, after the time we've invested in you.\n\nWe can talk later, though. Your training is the only important thing now.", objectives = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1718] = { id = 1718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Islander", description = "Your renown as a warrior grows, {name}.  Now it is time to pit yourself against your peers and see where you stand.\n\nThere is an island off the coast of the Barrens, south of Ratchet.  It is called Fray Island and it is a place where warriors meet.\n\nMeet, and fight.\n\nSpeak with the chief warrior of Fray Island, Klannoc Macleod.  If he finds you worthy, then Klannoc will lead you further down the warrior's path.\n\nTo reach Fray Island, search for the sand bar shallows along the Merchant Coast.", completion = "Hello, {class}.  It's good to see you made it to Fray Island.  I hope you find it to your liking...", objectives = "Speak with Klannoc Macleod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1719] = { id = 1719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Affray", description = "If you want to learn from me, then you must first pass The Affray.  It is a challenge we on Fray Island like to offer rising warriors who think they're tough, and if you can pass this test then I'll know you are.\n\nTo begin, walk into the middle of that crowd yonder and step on the grate.  That'll tell Twiggy Flathead you're ready, and he'll send challengers against you.\n\nBeat all the challengers and he'll call out Big Will.  Kill Big Will, and return to me in the time we allow.", progress = "Have you completed your challenge?", completion = "Well done, {name}.  You have passed The Affray!\n\nYou are a worthy {class}, and I am honored to teach you...", objectives = "Kill Big Will, then speak to Klannoc Macleod on Fray Island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1738] = { id = 1738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heartswood", description = "In preparation for your coming, I used my sight to look over the world and through the mists of time. I have found what it is you seek.\n\nIn the War of the Ancients, two lovers fell together in battle. Where they took their last breaths, a tree known as the heartswood grew, a symbol of their undying love.\n\nThat should be enough to tempt a succubus. You will find it in the ruins of Ordil'Aran in the northwestern part of the forest of Ashenvale.", progress = "Was your search a success, {name}?", completion = "Yes, I can tell this will do nicely, let me just work with it for a moment...\n\nTakar is a resourceful fellow to have around, isn't he? If only I could persuade him to move back to civilization.", objectives = "Retrieve the Heartswood from Ashenvale and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1739] = { id = 1739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "Using the heartswood core, you will be able to cast a spell at the summoning circle in the crypt below to open a portal for the succubus to pass through.\n\nBe careful, {name}, succubi have overrun even the strongest of minds.\n\nOnce you have bested and returned it to the void, return to me and I will show you how to call and control it.", progress = "Sometimes I wonder if Surena was not a succubus in disguise, sent to warp and twist my mind... Ha! I give her too much credit, I think.", completion = "Well done, well done, {name}. I see we've done right in deciding to train you. Your performance certainly does not disappoint.\n\nI've no qualms in showing you the way to control your newly bound succubus. Observe carefully.", objectives = "Using the Heartswood Core, summon and subdue a succubus, then return the Heartswood Core to Gakin the Darkbinder in the Slaughtered Lamb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1740] = { id = 1740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Orb of Soran'ruk", description = "When demons of the Legion fall out of favor, their spirits are imprisoned within orbs and distributed to their mages and warlocks.\n\nMany were carried by their servants in Azeroth. Even fragmented, they still possess the powers of the demons trapped inside.\n\nThe orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps. The other, larger piece, was possessed by a wizard in Shadowfang Keep. Find them and I can reform it.", progress = "It took me many years to collect the pieces of the orb of Zargain, but it has served me well, as I am sure the orb of Soran'ruk will serve you.", completion = "Yes... The orb was not greatly fragmented, and almost all of the pieces are here. It is a simple thing to recreate them, to make Soran'ruk whole again.\n\nI have dedicated my life to the study of the Burning Legion's orbs and their recreation. You have done me a favor collecting these pieces to study, and I will give you them back--fully reconstructed--in a form of your choosing.", objectives = "Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1758] = { id = 1758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of the Cabal", description = "It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.\n\nMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.\n\nPerhaps Krom Stoutarm can help you with this. An itinerant warlock these days, he spends his days hoarding ancient texts and skulking about the library in Ironforge.", completion = "Tome of the Cabal? Hmm... sounds familiar. I've never seen it here before, though--and believe me, I remember every book I read.\n\nHmm...\n\nAh, yes! I have seen references to it in library cataloguing books.", objectives = "Speak with Krom Stoutarm in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1778] = { id = 1778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "I'm going to see about making plans to return home soon. Hopefully, Stephanie is doing well back in Stormwind. I can't wait to see her again. Till next we meet, {class}.", completion = "So, you've returned so quickly, huh? And what pray tell have you accomplished in your time away from here?\n\nWere you able to help a noble cause? Perhaps you've learned the value of charity or some more about your obligations to the citizens of Azeroth. Tell me, who have you helped and how.... Impressive, {name}, those are surely the actions of one who follows the Light.\n\nSuch sacrifice will always be rewarded in time.", objectives = "Speak to Tiza Battleforge in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1779] = { id = 1779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "I want you to take this, {name}. It is called the Symbol of Life.\n\nYou've proven charitable and patient, and now I want you to prove just how adept you've become in both combat, and power.\n\nMy husband Muiredon returned recently from an encounter with some Dark Iron dwarves, and he barely escaped with his life--he's over there having his wounds healed by one of our priests.\n\nTake the Symbol and speak to him. If you can help him, then we will speak again soon. May the Light shine upon you.", sourceObjective = "Take the Symbol of Life and speak to Muiredon Battleforge in Ironforge.\n\nProvided item:", completion = "*cough*\n\nGood day to ya, {class}. Don't mind me wounds, the good priest 'ere'll take care of ol' Muiredon in time. Not needin' the power of that Symbol of Life ya got there quite yet.\n\nSo, me wife sent ya o'er to speak to me, huh? Fair 'nough. I'll take the time to talk to ya--I'll tell ya exactly wut happened to Muiredon and his best friend Narm, a {class} jus' like yerself.", sourceObjectiveStatus = "unverified-source-field" }
quests[1780] = { id = 1780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "I'll take these to the children this very day. Please be safe, good {class}. It is not often <men/women> of your character show their faces in the city, but you've proven that the paladins here in Stormwind shall never turn their backs on those in need.\n\nFarewell.", completion = "You've returned so quickly, {name}. And what have you accomplished in your time away from the Cathedral?\n\nHave you helped a noble cause? Perhaps you've learned the value of charity or some more about your obligations to the citizens of Azeroth. Tell me, who have you helped and how.... Well, I'm impressed, {name}, those are surely the actions of one who follows the Light and values others above oneself.\n\nSuch sacrifice will always be rewarded in time.", objectives = "Speak to Duthorian Rall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1781] = { id = 1781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "Take this, {name}. It is called the Symbol of Life.\n\nYou've proven charitable and patient, and now the time has come to see if you're powerful enough to focus one of the Light's greatest gifts.\n\nMy friend Gazin returned recently from an encounter with some Defias in Elwynn near Heroes' Vigil--he barely escaped with his life. He's near the altar having his wounds healed by our priests.\n\nTake the Symbol and speak to him. If you can help him, then we will speak again soon. May you bask in the Light's glory.", sourceObjective = "Take the Symbol of Life to Gazin Tenorm in Stormwind.\n\nProvided item:", completion = "*cough*\n\nPleasure to meet you, {class}. Don't mind my wounds, the good priest here can take care of ol' Gazin this time. I won't be needing the power of that Symbol of Life you've got there... not yet anyway.\n\nSo, Duthorian sent you to speak to me, huh? Fair enough. I'll tell you exactly what befell me and my friend Henze. And with any luck, and some skill on your part, perhaps you can still help us all.", sourceObjectiveStatus = "unverified-source-field" }
quests[1782] = { id = 1782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furen's Armor", sourceObjective = "Here's your armor, {name}.  This will stand up to the strongest assaults or my name isn't Furen Longbeard!\n\nAnd I have to thank you.  I learned a lot while working with the materials you brought me.  I think I'll have another breakthrough one day!\n\nI'm going to send what I learned to other blacksmiths of the Alliance.\n\nI'll tell them you were a big help, and maybe they'll want to return the favor.", sourceObjectiveStatus = "unverified-source-field" }
quests[1783] = { id = 1783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "We was spyin' on some of the Dark Iron dwarves that've bunkered down south of Helm's Bed Lake. We knew they was up to no good, so Narm an' me thought we'd take a closer look--got ta see their leader given orders to some o' his men.\n\nNarm an' me took the chance to kill a few of 'em, but they proved tougher than we thought, an' more of 'em got the jump on us. Narm tol' me to run an' get support, so 'ere I am.\n\nNarm needs help, an' I'll not rest till he gets it.\n\nC'n ya help, {name}?", completion = "I can't thank you enough, brother.\n\nI can only assume that Tiza and Muiredon sent you here to aid me if you carry the Symbol of Life.\n\nIt's true, I fell to the Dark Iron while trying to attain one of the scripts: I was able to hold on long enough to allow Muiredon to escape, but the Light had almost embraced me fully when you came along. The fact that you were powerful enough to use the Symbol means great things for you, but there's time to speak of that later.", objectives = "Take the Symbol of Life and resurrect Narm Faulk in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1784] = { id = 1784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "Before I fell in battle, Muiredon and I had almost defeated one of the Dark Iron spies near that small house. We witnessed their captain passing orders to them, and sought to kill him and take the orders.\n\nSome of the council in Ironforge do not yet believe the presence of Dark Iron dwarves exists in Dun Morogh. By attaining one of those scripts, we'll not only have proof of their movements, but possibly an idea of what they're planning.\n\nGet one of those scripts and take it back to Muiredon, {name}.", progress = "Yer back! I'm glad to see it, {name}. My wounds are healed and I'm about ready to return to Helm's Bed lake as soon as I c'n convince me wife that I'll be fine.", completion = "Haha! You've done it! Ya saved Narm, and ya found the proof me wife needs to take to the council. Yer a blessin' o' the Light if I ever saw one... not includin' me wife o' course.\n\nThank ya again, {name}.", objectives = "Retrieve a Dark Iron Script from the Dark Iron dwarves near Helm's Bed, and return to Muiredon Battleforge in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1785] = { id = 1785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "I c'n see me wife's o'er there beamin' wit pride already. Ya better get yer tuchus o'er there pronto. I be thinkin' she'd have some words wit ya.\n\nLight be witcha, mighty {class}. I'll be lookin' fer ya on the battlefield against the Scourge and dem Dark Irons when the time comes.", completion = "You've done all of Ironforge a great favor today, {name}. I'm proud to count you among us, and if you feel you're ready, I would like to bless you with this scroll. The Symbol of Life would only have worked when used by a {class} who was ready for one of the Light's greatest blessings--the power to restore the dead back to life.\n\nI will teach you the ability to resurrect your companions. Use it wisely, {name}, and thank you, on behalf of myself, my husband, and Ironforge.", objectives = "Speak to Tiza Battleforge in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1786] = { id = 1786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "Henze and I had made it to Heroes' Vigil, an island in the middle of Stone Cairn Lake in northeastern Elwynn. We'd heard the Defias had infiltrated our borders and we wanted proof to take to the king's advisors.\n\nWe caught sight of a couple of the scum going over some documents, and we attacked. Unfortunately, we were quickly overwhelmed by more of the mages.\n\nHenze held them off for me while I escaped... the daft fool, going and being brave.\n\nHe's out there now, Henze is. Can you help us, {name}?", completion = "Thank you, brother.\n\nSeeing you wield the Symbol of Life, may I assume Duthorian or Gazin sent you?\n\nI fell to the Defias spell casters while Gazin and I tried to get their plans from them: I was able to hold on long enough to allow Gazin to escape, but in the end, their magics overwhelmed me.\n\nBut you were able to bring me back: the ability to use the Symbol doesn't come to just anyone, {name}. It bodes well for you that you were able to empower it with your own faith.", objectives = "Take the Symbol of Life and resurrect Henze Faulk in Elwynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1787] = { id = 1787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "We'll have time to talk more about the Symbol at a later time. What's important now is to get those papers we saw the Defias going over. If we can get our hands on them, we'll be able to prove the Defias have infiltrated Elwynn and hopefully gain some insight into what their plans are.\n\nI'm in no shape for battle as of now, {name}. Do you think you're strong enough to get those papers from the Defias here on the island?\n\nIf you're able to get them, bring them back to Gazin and let him know I'm all right.", progress = "Is Henze safe, {name}? Were you successful?\n\nBetween your skill with a weapon, and the power of the Light, I'd imagine Heroes' Vigil is safe from any Defias threat, but that's for the King and his advisors to say.", completion = "Wonderful! You made it, and saved Henze. The Light is with you for sure, {name}!", objectives = "Retrieve a Defias Script from the Defias Rogue Wizards in Elwynn, and return to Gazin Tenorm in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1788] = { id = 1788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Divinity", description = "I'll take the script to the King's advisors after Duthorian's taken a look at them, but in the meantime, you should go speak to Duthorian now. He'll be wanting to pat you on the back for sure!\n\nThank you again, {name}. I hope we meet again. You're surely an ally I'm proud to call friend.", completion = "You've done well this day, {name}. You should take some pride in what you've accomplished.\n\nEven more so, you should be proud of your abilities. Not everyone can use the power of the Symbol of Life. Calling upon the Light to bring back the dead means you're prepared for one of the {class}'s greatest honors: the power of resurrection.\n\nYou shall have the power to bring back fallen companions much like you did for Henze.\n\nBe well, {name}. The Light shines upon you and you should welcome it wholly.", objectives = "Speak to Duthorian Rall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1789] = { id = 1789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Symbol of Life", sourceObjective = "If you fail to help Narm after you've used the Symbol of Life, {name}, then return to me and I shall give you another.\n\nIt is important to both my husband and I that you return successful. Please, make haste.", sourceObjectiveStatus = "unverified-source-field" }
quests[1790] = { id = 1790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Symbol of Life", sourceObjective = "Make haste, {name}, more than one life hangs in the balance if you fail.\n\nIf for some reason you fail to help Gazin and Henze, then return to me and I will give you another Symbol of Life for your travels.\n\nDon't mistake my aid as simple charity, you must prove yourself worthy like any other {class} and continual failure may reflect upon you later.", sourceObjectiveStatus = "unverified-source-field" }
quests[1791] = { id = 1791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Windwatcher", description = "Now that you've learned your berserker's stance, you'll want a nice weapon to use it with.\n\nTalk to Bath'rah the Windwatcher, a troll hermit who lives between the Alterac Mountains and the Western Plaguelands.  He is a skilled weapon maker and a powerful shaman.\n\nTo find Bath'rah, go to the river that flows along Tarren Mill's eastern flank.  Follow it north--Bath'rah is camped near ruins that rest along the river's eastern bank.", completion = "You have traveled far, young {class}.  I see fire in your eyes.  You seek a weapon of great power, yes?\n\nI can help you with your quest.  And you can help me with mine.", objectives = "Speak with Bath'rah the Windwatcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1792] = { id = 1792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whirlwind Weapon", sourceObjective = "I have the whirlwind heart, and am ready to place it within your vessel of choice.\n\nChoose your weapon, {name}, and know that its power is the power of Cyclonian.", sourceObjectiveStatus = "unverified-source-field" }
quests[1793] = { id = 1793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Valor", sourceObjective = "It has been proven that the Light is with you, {name}, but as times grow more dangerous, it becomes important to know what strength lies beneath the flesh. When demons, dragons, or any other evil set foot in your lands, your mettle will be tested. Will you be strong enough?\n\nBravery, regardless of the situation, is as much a part of paladinhood as the Light, your armor, and your weapon. Protecting the weak, and not losing faith are two more lessons you must master while you study in the Cathedral of Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[1794] = { id = 1794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Valor", sourceObjective = "It has been proven that the Light is with you, {name}, but as times grow more dangerous, it becomes important to know what strength lies beneath the flesh. When demons, dragons, or any other evil set foot in your lands, your mettle will be tested. Will you be strong enough?\n\nBravery, regardless of the situation, is as much a part of paladinhood as the Light, your armor, and your weapon. Protecting the weak, and not losing faith are two more lessons you must master while you study in the Cathedral of Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[1795] = { id = 1795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "If you're are sufficiently prepared, then we should begin. Let me explain the process to you.\n\nI will begin by creating the basic summoning circle. When that is finished, my acolytes will use the rods of channeling to create the greater circle.\n\nOnce that is done, read the incantation from the Tome of the Cabal, and the felhunter will be pulled forth. Be careful, {name}. A felhunter is a powerful foe, and I'd like to see you keep your head on your shoulders.", progress = "Every {class} should have a felhunter at his command. Though it be difficult to tame, the powers it brings to its master far outweigh the cost.", completion = "I must say I'm impressed, {name}. When I faced down my felhunter, I barely escaped with my life. I sense that you have the potential to become one of the most powerful warlocks of this era.", objectives = "Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1796] = { id = 1796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Components for the Enchanted Gold Bloodrobe", description = "The first item I will aid you in creating is a robe. You will gather the items for me, and we will put them together. Afterwards, assuming you succeed, you will have the first of many items that will make you more powerful and aid you in your struggles.\n\nTo start, you must have crafted Robes of Arcana. A tailor can make this for you, or perhaps you can purchase one from someone else--I'd be most impressed if you could make it yourself--but regardless, bring me the robes, and we shall go from there.", progress = "How goes your search for the robes, {name}? Have you created them yourself? Such personal touches I find make the imbuing of magic that much sweeter. It gives you a greater sense of accomplishment. But I understand if you choose the quicker path and have it made for you--there's something to be said for such... ambition.", completion = "This will do nicely, {name}.\n\nAll magical items must begin with an item of high quality. The more effort and skill put into an item, the greater the magics it can hold. Rare and more expensive components hold the magic better. You will not regret having the robes fashioned into the ones we will make for you later on.", objectives = "Bring Robes of the Arcana to Menara Voidrender in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1798] = { id = 1798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Strahad", description = "It is time you learned the felhunter summoning, {name}. I do not have the reagents and items necessary to teach you here, so you will have to seek out another, Strahad Farsan, another of our inner circle.\n\nHe makes his residence in the goblin port of Ratchet. I will send word ahead of you to inform him of your coming.", completion = "{name}? Ah, of course. Our latest prodigy. The real thing can't live up to the legend, I'm afraid.\n\nNo matter, you've come here to learn, not to hear me make jokes to myself.", objectives = "Speak with Strahad Farsan in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1799] = { id = 1799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragments of the Orb of Orahil", description = "Good, then we shall begin.\n\nThe first thing you must do is speak to my acolytes inside. Choose one of their paths to follow--they will explain more.\n\nSecond, you must travel to Desolace and find an Infernal Orb from one of the warlocks of Mannoroc Coven. It is that orb that you will cleanse with the help of a mage named Tabetha deep in southern Dustwallow Marsh. She will aid you because of our history together.\n\nAgain, do not come back until you have done both things I've asked.", progress = "And obviously not being a mage, I wonder if I can trust you at all. I can smell the power of the arcane on you, but you seem to have eluded the stank of corruption that comes so willingly with your kind.\n\nYes, a {class}... a {class} has come to ask for my help.\n\nWell, what is it I can do for you, {name}?", completion = "Oh, so Menara sent you. Fair enough... I suppose you may stay as my guest for the time being. But you must be on some pressing business--perhaps you're here seeking lost power? Maybe I'm mistaken. Maybe corruption isn't too far away from you after all.", objectives = "Speak to Menara's acolytes inside the tower above Ratchet and choose one of their paths to follow.\n\nAfterwards, bring an Infernal Orb to Tabetha in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1800] = { id = 1800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lordaeron Throne Room", description = "The orphan matrons at my home tell mighty stories of battle and lore at night if we are good and do our chores.  One story was about how Lordaeron fell, and about how the evil Arthas took his own father's life to become ruler.\n\nHe had no honor, {name}!  When I grow up and become a mighty Horde warrior, my blade will be guided by honor - never evil!\n\nWould you take me to see the throne room, please?  It is just before where you would go down into the Undercity.", progress = "Are we there yet?", completion = "That throne room was scary, {name}!  Even though it was empty, it felt like a great evil had happened there.  I felt mad... but I also felt sad too.  I understand why the matrons tell us such stories; I will never betray my people like that!\n\nThank you for taking me to the throne room, {name}.  I learned a lot.", objectives = "Take your ward to the old Lordaeron Throne Room that lies just before descending into the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1801] = { id = 1801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of the Cabal", description = "It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.\n\nMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.\n\nPerhaps Jorah Annison can help you with this. He's employed as a cartographer in the Undercity these days, but still knows more of ancient texts than any I know.", completion = "Map making! Pictures, estimations of reality. I have no use for such things.\n\nIn books, narrative, description! That is where truth lies. I would trade all the maps in this store for one book on the rise of necromancy, or a tale of the Dark Lady's triumph.", objectives = "Speak with Jorah Annison in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1802] = { id = 1802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of the Cabal", description = "It was lost, but there's some idea as to where it might be found.\n\nThere was only one copy ever made and it was vandalized at some point, a large portion of it ripped from the binding. Rumor has it that it somehow passed into the hands of the centaur of Thousand Needles.\n\nThe rest was lost off the coast west of Southshore, where it was to be transported to Menethil Harbor by boat. It never arrived.\n\nIn exchange for this knowledge, all I ask is that if you find it, bring it to me to see.", progress = "Did the rumors prove true, {name}?", completion = "Fantastic! Now I may join the ranks of the few that have spied its contents.\n\nI can't wait to further peruse this text. This is a great day, {name}! If you will just allow me to glance at it before you leave. I'm sure that Strahad will be willing to send me a copy.", objectives = "Retrieve the Moldy Tome and Tattered Manuscript for Krom Stoutarm in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1803] = { id = 1803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of the Cabal", description = "Ah! I see that you are a warlock of similar tastes to mine. Indeed, acquiring the Tome of the Cabal is a worthy aspiration. Did you know that it was once held within the walls of Lordaeron? It was vandalized though, almost half its pages removed. Who would commit such a heinous act?\n\nThat half is lost, though rumor says that it fell into the hands of the centaur of the Thousand Needles.\n\nThe rest of the text was to be transferred to Ironforge, but was lost in transit on the coast west of Southshore.", progress = "It may be that you are chasing after fairy tales, {name}, but truth can be found at the center of even the wildest rumors.", completion = "Well well well! What do we have here?\n\nThis is impressive, {name}. I wouldn't have thought it possible, but here it is in my very hands, the complete Tome of the Cabal.\n\nAllow me to leaf through its pages for just a moment before you are off again.", objectives = "Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1804] = { id = 1804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of the Cabal", description = "Well, ah, it's hard to let it go. But you found it, and you have more important things to do with it, of course. Just, please, be sure to mention to Strahad that I wanted a copy.\n\nWhile you were out, he sent a message for you. He wanted me to tell you that for his acolytes to assist with the summoning, you'll have to acquire three rods of channeling.\n\nHe might not know where to find them, but I do! They were last used by the orcs of the Dragonmaw clan in the Wetlands. I'd check their spellcasters!", progress = "Haven't seen you around these parts for a while. Have you found the tome and the rods?", completion = "Well done! The Tome of the Cabal and three pristine--slightly scratched, I suppose--rods of channeling.\n\nThis will be interesting. It's been some time since a young {class} took on a felhunter to make his own.", objectives = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1805] = { id = 1805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of the Cabal", description = "This is one of the most interesting texts I have perused in the last few years. The selection here is sparse--mostly books on geography--and I have already read them all. I should hope that Strahad would send me a copy of this tome when he has the chance.\n\nSpeaking of him, he sent word to me while you were away. For your task, you must obtain three rods of channeling.\n\nFor allowing me to look at this text, I will share a secret: You can find the rods on orcs of the Dragonmaw Clan in the Wetlands.", progress = "Yes, {name}? Of what service can I be to you?", completion = "Well done! The Tome of the Cabal and three pristine--slightly scratched, I suppose--rods of channeling.\n\nThis will be interesting. It's been some time since a young {class} took on a felhunter to make his own.", objectives = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1806] = { id = 1806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Test of Righteousness", description = "Why don't we go over to the forge and get started on this? I've been preparing for your arrival for some time, so it shouldn't take long at all.\n\nWhen we're done, you'll be far more prepared to defend the Light than you have been, this much I swear.\n\nI'll be somewhat honest, {name}, seeing the results of your exploits makes me somewhat envious. But knowing that I can contribute to your adventures in my own significant way does bring me some joy.", completion = "Here it is, {name}. A weapon worthy of a champion of the Light such as yourself. I've named it after a great dwarven {class} who was a friend of mine. His name was Verigan... Bosch Verigan. Please take it on behalf of myself and my wife. We owe you a great debt, and the world will be a safer place with one of your skill traveling the land.", objectives = "Wait for Jordan Stilwell to finish forging a weapon for you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1818] = { id = 1818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Dillinger", description = "I was told Deathguard Dillinger has a job for someone like you.  If you're willing to show your value to the Dark Lady's forces, then report to Dillinger immediately.\n\nDeathguard Dillinger's post is on the west end of Brill, near the graveyard.", completion = "You're here for a mission?  Good.  I have an important one, and one that will test your skill in combat... and your resolve in the defense of the Forsaken.", objectives = "Speak with Deathguard Dillinger in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1819] = { id = 1819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulag the Cleaver", description = "When the Scourge swept through Tirisfal Glades, we captured one to study.  He had a free mind, and called himself Ulag the Cleaver.  But, although his will was free, he was still enthralled by the Lich King.\n\nWe hoped to find a way to break the king's control over Ulag, but we failed.  Now, finally, it is time to free him.  \n\nFree him, and kill him.\n\nActivate the skull stone trigger near the mausoleum to the north.  This will lift the magical seal that binds him.\n\nThen... be ready, {name}.", progress = "Your task is yet undone, {name}.  It is not wise for a {class} to show fear...", completion = "Well done, {name}.  Ulag was no minor agent of the Scourge.  You have shown the Deathguards, and hence the Dark Lady, that you are a {class} of skill and resolve, and are worthy of further instruction.", objectives = "Kill Ulag the Cleaver, then speak with Deathguard Dillinger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1820] = { id = 1820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Coleman", description = "You have proven your value to the Dark Lady, now perhaps you can prove yourself to one of her subjects.\n\nColeman Farthing awaits a warrior who is willing to be his instrument of revenge against the Forsaken's enemies.\n\nYou will find him in the Gallow's End Tavern in eastern Brill.", completion = "Yes, it is true.  I have need for your skills in combat.  My means are small, but my task aids both me and the Forsaken's cause.  Do it, and your reward will be twofold.", objectives = "Speak with Coleman Farthing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1821] = { id = 1821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamand Heirlooms", description = "The Agamand family were my employers in life, and they were the cause of my death!  It is fitting that the Agamands are now mindless minions of the Lich King.\n\nNow I would have their last vestiges of honor.  Go into their family crypt and rob them of their family heirlooms: a sword, an axe, a dagger and a mace.  Bring them to me!\n\nThe Agamand family crypt is at the north end of the Agamand mills, protected by lurking scourge and dead Agamands.", progress = "Do you have the heirlooms, {name}?", completion = "Ah!  You retrieved them!  Now the last semblance of honor and memory is stripped from the cursed Agamand lands.  The family truly is no more!", objectives = "Bring Coleman Farthing the Agamand Family Axe, the Agamand Family Sword, the Agamand Family Mace and the Agamand Family dagger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1822] = { id = 1822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heirloom Weapon", sourceObjective = "I will keep three of the weapons you returned to me, as mementos of my pain and loss.  But please, {name}, choose your favorite of the heirlooms and keep it for yourself.\n\nMay it serve you greater than it served its cursed, former owners.", sourceObjectiveStatus = "unverified-source-field" }
quests[1823] = { id = 1823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Ruga", description = "You are a warrior of skill and growing renown.  Perhaps you are ready for Ruga Ragetotem's trial?  If so, then find Ruga in Camp Taurajo in the Barrens.\n\nHe awaits those warriors who answer his call.", completion = "You are here for my trial, {name}?", objectives = "Speak with Ruga Ragetotem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1824] = { id = 1824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial at the Field of Giants", description = "To pass this trial, you must travel south to the Field of Giants.  There you will find a host of crawling, insect creatures.  They are new to the Barrens and I do not like what they herald.\n\nBring me their still-twitching antennae, and waste no time, {name}, for harvested antennae will not twitch for long.  Bring me the antennae in the time allowed, and you will pass the trial.", progress = "Do you have the antennae?  If so then give them to me quickly, for twitching antennae do not twitch forever...", completion = "Nicely done, {name}!  In passing the trial at the Field of Giants, you take one more step down the {class}'s path.", objectives = "Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1825] = { id = 1825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Thun'grim", description = "Thun'grim Firegaze, an orc blacksmith of renown, has heard of your continued deeds of valor in service of the Horde.  He would like to fashion for you a suit of armor, and bids you speak with him immediately.\n\nThun'grim is camped east of the Crossroads in the Barrens.", completion = "Yes, you have come.  This is good, for we have much to discuss, you and I.", objectives = "Speak with Thun'grim Firegaze in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1838] = { id = 1838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutal Armor", description = "I have heard tales of your strength and valor, and wish to make for you a suit of armor, a companion to aid you as tales of your great deeds grow.\n\nBut the fashioning of this armor will be a quest unto itself, {name}.  I will need your help, and the help of other smiths of the Horde.\n\nHere, take this scroll.  I spent many nights, struggling with near-blind eyes, writing that which I need for the armor.  Bring me the items on this scroll and I will create for you the first piece of the suit.", progress = "Do you have the items on my scroll, {name}?", completion = "You brought all that I asked.  Now, I will do my part...", objectives = "Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1839] = { id = 1839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ula'elek and the Brutal Gauntlets", description = "The troll smith Ula'elek will craft for you the brutal gauntlets.  He dwells in Durotar, in Sen'jin Village with his Darkspear brethren, and he awaits your coming.", completion = "Greetings, {name}.  Old Thun'grim sent word to me of your coming, but had he kept silent your presence here would not have surprised me.\n\nThe spirits follow your progress, young {class}, and they tell me that many foes have fallen before you.", objectives = "Speak with Ula'elek in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1840] = { id = 1840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orm Stonehoof and the Brutal Helm", description = "Orm Stonehoof is respected greatly for his skill.  He will make for you the brutal helm.\n\nSeek him out in Thunder Bluff, near the pool by the city's great, central totem.", completion = "Greetings, {class}.  I am Orm, and Thun'grim tells me you wish a helm made?", objectives = "Speak with Orm Stonehoof in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1841] = { id = 1841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Velora Nitely and the Brutal Legguards", description = "It is said that, before her death, Velora Nitely was one of the finest armorsmiths in Lordaeron.  Death, it seems, has not decreased her talents.  Speak with Velora--she will make your brutal legguards.\n\nVelora plies her trade in the Undercity of Lordaeron, in the trade quarter.", completion = "You are here for leg armor?  Great!\n\nUm... am I making the armor for you, or are you making it for me?\n\nThat was a joke.  Was it funny?  I can't tell... I lost my sense of humor the same time I lost my sense of smell.  Which was about the same time I stopped breathing.", objectives = "Speak with Velora Nitely in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1842] = { id = 1842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyr Hooves", description = "I can make you a pair of brutal gauntlets, and great magic will they hold.  But first, you must collect this magic and bring it to me.\n\nThe satyrs dwell in northeastern Ashenvale because of the forest's power.  They feed off its purity, leeching and corrupting.  You can tell which satyrs have drawn the most of Ashenvale's magic by their swollen, uncloven hooves.\n\nThese hooves hold great power.  I will need them for your gauntlets' crafting.", progress = "Do you have the hooves, {name}?  The magic within them is strong.", completion = "Ah, you have them!  Now, just as the Satyrs leeched the strength of Ashenvale, I will leech the power held within these hooves and harness it into my crafting...", objectives = "Bring 7 Uncloven Satyr Hooves to Ula'elek at Sen'jin Village in Durotar", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1843] = { id = 1843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutal Gauntlets", sourceObjective = "Thank you, {name}.  These gauntlets are my best work.  Take them. In wearing them, you bring honor to me and my ancestors.", sourceObjectiveStatus = "unverified-source-field" }
quests[1844] = { id = 1844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chimaeric Horn", description = "I will make you the helm, but you must show me you are worthy of it.\n\nNestled in the northwestern reaches of the Stonetalon Mountains there lies the Charred Vale.  It was once a verdant place, but is now defiled and ashen, and what creatures remain there are mad with pain and despair.\n\nThat place is where I send you, {name}.\n\nYou must go to the Charred Vale and find a chimaera matriarch.  Slay her, free her of her misery.  Bring me her galvanized horn as proof, and I shall make for you the helm.", progress = "Do you have the horn?  Is the matriarch free of pain?", completion = "You have completed your task, {name}, and shown me your worth and resolve.  The helm will be yours...", objectives = "Bring a Galvanized Horn to Orm Stonehoof in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1845] = { id = 1845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutal Helm", sourceObjective = "I give this helm to you.\n\nGreat deeds brought you to me, {name}, and Earthmother willing... even greater deeds lie before you.", sourceObjectiveStatus = "unverified-source-field" }
quests[1846] = { id = 1846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Shinbones", description = "To make the brutal leg guards, I need a brace of sturdy shinbones.  The Dragonmaw orcs of the Wetlands have nice, thick shinbones.  I'll need theirs.\n\nBut they must be sturdy.  Be sure to test the shinbones as you collect them.  If you can break them with your bare hands, then they won't be sturdy enough to work with.", progress = "I'm waiting for those shinbones, {name}.  They'll make a nice frame for your leg guards.", completion = "Well done!  These all look strong.  I think they'll do quite nicely.  How did those orcs mind you taking their shins, {name}?  Complain much?\n\nThat was another joke.  You're not laughing.\n\nI'm not very funny these days, am I...", objectives = "Bring 8 Sturdy Dragonmaw Shinbones to Velora Nitely in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1847] = { id = 1847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutal Legguards", sourceObjective = "Here are your legguards, {name}.  Let me know how they fit or if you need any modifications.  I aim to please!  At least I used to.\n\nThese days I don't care much for my craft.  But it beats being a mindless minion of the Scourge!\n\nI guess.", sourceObjectiveStatus = "unverified-source-field" }
quests[1848] = { id = 1848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutal Hauberk", sourceObjective = "I am sure you endured much hardship and shed much blood on my task, {name}.  Here is the product of your toil.\n\nMay you wear it well, and may you one day return here with stories of its service to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[1858] = { id = 1858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shattered Hand", description = "I'll leave it to you to get Tazan's satchel open, and return to me with its contents. The locking mechanism is complex, so it would probably be easiest if you obtained the key.\n\nAs you didn't find it on Tazan's body, I can only assume that he left the key in the care of another... Ah, yes, that's right. He had an assistant named Gamon. A drunkard, you'll most likely find him at the tavern. Perhaps you could quietly relieve him of the key.", progress = "Is it not vexing to have the subject of your desire within your grasp, but to have no way of getting to it?", completion = "Hmmm, now this is interesting. You've more than proved your worth with this, {name}. I am quite impressed. Consider yourself the newest member of the Shattered Hand. And take this, it will be a great help to you in the future, I think.", objectives = "Steal Tazan's key, then use it to open his Satchel and deliver its contents to Therzok in the Cleft of Shadow in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1859] = { id = 1859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therzok", description = "Lower your voice, {name}. Yeah, I know your name. Was told to keep an eye out for an orc by your description.\n\nFrom what we've heard about you, you can handle yourself in combat, and aren't opposed to a little sneakery from time to time.\n\nAm I right?\n\nAnyways, you should go see Therzok in Orgrimmar. He's got an offer for you to hear.", completion = "Very good, I'm glad Kaplak was able to get a hold of you.\n\nWe have some things to speak of, not the least of which is your future with the Hand.", objectives = "Speak with Therzok in the Cleft of Shadow in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1860] = { id = 1860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Jennea", description = "We mages have a task that needs doing.  One that is vital to the safety of Stormwind and Elwynn forest.\n\nJennea Cannon has the details.  She studies in the wizard's sanctum, in the mage district of Stormwind.  You should make your way to her with haste.", completion = "You have been sent to aid me in my task, {name}?  Good.  It is heartening to see young mages eager to help in our cause...\n\nWhat cause, you ask?  In time, young one.  You shall know... in time.", objectives = "Speak with Jennea Cannon in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1861] = { id = 1861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirror Lake", description = "This world has been victim to massive mystic struggles, which tore magic currents from once stable channels.  We struggle to determine the effects these changes have caused, and some of us fear the worst!\n\nBut I will reveal more of this later.  Right now, we need you to gather information.\n\nHere, take this flask.  Go to the base of the waterfall at Mirror Lake, southwest of the Stormwind gates, and retrieve a sample of the water there.  Return it to me so that I might test it for magical taints.", progress = "Do you have the sample, {name}?  The flow of magic in Stormwind and Elwynn has been altered, and I must know if it is seeping into the water.", completion = "Thank you, {name}.  I will test this water for magical properties.  Let us hope that it contains none, or we may find that those who drink from Mirror Lake for too long will be adversely affected.\n\nHere, {name}.  Take this orb or staff as a token of your service.  May it serve you well.", objectives = "Bring a Mirror Lake sample to Jennea Cannon in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1878] = { id = 1878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water Pouch Bounty", progress = "Back again, {name}?  If you have five more Wastewander water pouches, then I have a care package with your name on it!", completion = "Excellent - the more water pouches we are able to reclaim, the further away from disaster we'll all be!  Keep 'em coming, and I will be sure to reward you for every five water pouches you bring me." }
quests[1879] = { id = 1879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Bink", description = "{name}!  Bink, my gnome colleague in Ironforge, sends word.  She has a task that needs doing and won't rely on anyone but a mage to do it!  Are you that mage, {name}?\n\nIf so, then speak with Bink.  She spends her time in the Hall of Mysteries in the Mystic Ward of Ironforge.", completion = "Oh, I can see you have promise, yes you do! But it takes more than promise to be a good {class}.  And if you're not a good {class}, then you're a bad {class}.  And bad mages are part of the problem, yes they are!\n\nOops, I'm getting ahead of things.  Let's begin at the start!", objectives = "Speak with Bink in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1880] = { id = 1880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage-tastic Gizmonitor", description = "We mages do more than just waggle our fingers and make pretty sparks!  We control magic, the base fabric of our world!  And that takes great care, and resolve.  And knowledge... so much knowledge!\n\nOne of my devices, the mage-tastic gizmonitor, collects and stores that knowledge in huge amounts!  But it's lost!  When we fled our home of Gnomeregan, I left it in a chest in one of our huts outside the city, and now the place is crawling with leper gnomes!\n\nPlease, {name}, retrieve my gizmonitor!", progress = "Did you find the gizmonitor?  I must have it before its energy supply runs out!", completion = "Oh, splendid day!  When I made the gizmonitor I never realized how dependent on it I would become.  Now I can begin my studies anew!\n\nThank you, {name}!  And here--these were my first tools as a {class}.  They're a little scratched but they're well tested.  Take your pick--I'm sure you'll find either of them useful.", objectives = "Bring Bink her Mage-tastic Gizmonitor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1881] = { id = 1881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Anastasia", description = "{name}, Anastasia Hartwell has a task for someone of your talents.  Speak with her in the Magic Quarter of the Undercity, and prepare yourself for your first task for the mages of the Forsaken.", completion = "Greetings, {name}.  You were wise to answer my call, and wiser still if you heed what I next say...", objectives = "Speak with Anastasia Hartwell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1882] = { id = 1882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Balnir Farmstead", description = "The Plaguelands to the east are an aberration.  Devised by the Lich King, they spread their magic into the soil, corrupting and killing all that live.  Although there is a certain charm to the destructive forces of the plague, we, the mages of the Forsaken, believe it is unruly and must be curtailed.\n\nBut first, we must measure how far it has spread into Tirisfal.  Go to the Balnir Farmstead in eastern Tirisfal.  In the garden are flowers--snapdragons.  Gather these and return.", progress = "Do you have the snapdragons?  That breed of flower is highly receptive to magic energies, and studying the snapdragons so close to the Plaguelands can tell us if the plague has entered Tirisfal Glades.", completion = "Ah, a fine specimen this is.  I will send it to be studied by our apothecaries to determine the extent of the Plagueland's taint.\n\nWell done, {name}.  For your services, I present to you this choice: an orb or staff.  Whichever you choose, you will find it quite useful.", objectives = "Bring Balnir Snapdragons to Anastasia Hartwell in the Mage Quarter of the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1883] = { id = 1883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Un'thuwa", description = "Un'thuwa, tribal mage of Sen'jin Village, detects a disturbance in the magic currents of Durotar and asks for aid.  Speak with Un'thuwa and do what you can to help him.\n\nDo this, and in time further secrets will be revealed to you.", completion = "Hail, {name}.  Praise to you, for my call for aid is now answered.  Let us hope you are up to the task...", objectives = "Speak with Un'thuwa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1884] = { id = 1884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ju-Ju Heaps", description = "The warlock Zalazane of the Echo Isles has disrupted the normal flow of magic in Durotar.  He does this through tainted fetishes, ju-ju heaps, which he has placed among his huts on the main Echo Isle.\n\nThese heaps corrupt our wildlife and give power to the warlocks and infernal creatures that lurk in the land's dark corners.\n\nYou must destroy the ju-ju heaps, {name}, before the flow of magic is forever altered.", progress = "You must hurry, {name}.  Destroy the ju-ju heaps!", completion = "I sense that Zalazane's ju-ju heaps were destroyed, and with time, and luck, the flow of magic in Durotar will return to normal.\n\nA great deed you have done for your people, {name}.  And you have shown your worth to us, the mages of the Horde.", objectives = "Destroy 4 Ju-Ju Heaps, then return to Un'thuwa in Sen'jin Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1885] = { id = 1885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mennet Carkad", description = "{name}? Not quite what I was expecting, considering Carkad himself has taken an interest to you. Looks can be deceiving though, right?\n\nEither way, you should go see him as soon as possible. You wouldn't want to know what happened to the last few that chose to ignore his summons.", completion = "Hm. No doubt you made your way here at first mention of my summons, yes? Of course. I would expect no less from a prospective Deathstalker.", objectives = "Speak with Mennet Carkad in the Rogues' Quarter of the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1886] = { id = 1886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers", description = "If you wish to join the Deathstalkers, Lord Varimathras' elite guard, you will have to prove your worth.\n\nI will not lie to you, {name}, this task could mean your death.\n\nI have some things that need attending to. I require the personal effects of Astor Hadren, a messenger who travels between Silverpine and the Undercity. I will leave the method of procurement to your discretion.\n\nIt will be better for you if you know less of the nature of this business. Succeed and I shall tell you more.", progress = "Success to report?", completion = "Well done, {name}. You've passed the first part of this test. Hopefully Andron will not have caught wind of your activities, and we will be able to convince him that you are, in fact, the messenger he is expecting.", objectives = "Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1898] = { id = 1898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers", description = "The letter of introduction should be enough to convince Andron that you are the messenger he's been waiting for. I've met Andron before, he doesn't quite have the mental capacity to be that suspicious.\n\nLord Varimathras suspects that Andron has been providing aid to some other group. He wishes to know what organization this is and requires proof of it.\n\nI want you to speak with Andron, and obtain this information. You'll find him at his shop near the Apothecarium.", progress = "Hello. Something I can do for you?", completion = "Ah, yes, I've been expecting you. I have no doubt our mutual acquaintances are pleased with the information that I have provided so far?\n\nI suppose there's no point in asking you, I doubt they would burden you with this knowledge. Why place so much trust in the messenger, hm?", objectives = "Speak with Andron Gant in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1899] = { id = 1899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers", description = "You'll find the ledger with the information your employers seek on the bookshelf behind me. Deliver it with my regards, and tell them that I would prefer it if they sent you, if they find enough value that they should wish to continue our arrangement.", progress = "Success, {name}?", completion = "Well, this is certainly more information than I suspected to get out of Andron. Give me a moment to peruse it, before I set you to your next task.", objectives = "Bring Astor's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1918] = { id = 1918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Befouled Element", description = "The slain elemental has produced an intensely glowing globe of water.  The contents of the globe are, at best, disgusting.  It would be safe to assume that whatever has befouled the water of Mystral Lake is most likely present in the water of the globe.\n\nIt's not exactly common knowledge who might be interested in such a find; perhaps the person who originally sent you out to the lake, Mastok Wrilehiss at Splintertree Post, might have an idea.", progress = "Yeah, what do you need?", completion = "You find a nasty ball of water and decide to bring it to me?  Who am I, the Earthen Ring or something?\n\nActually, that does give me an idea... perhaps you do need the Earthen Ring for this.  I mean, if it helps clear up the situation at the lake for good, then I'm all for it.\n\nYou know who the Earthen Ring are, {name}?", objectives = "Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1919] = { id = 1919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Jennea", description = "Your knowledge of the craft grows, young {name}.  Are you now ready to begin your true lessons?  Are you ready to take your place in the secret war we wage?\n\nIf so, then speak with Jennea Cannon, in the wizard's sanctum in the mage district of Stormwind.  She has a task for you which will open your first window into the invisible world.", completion = "{name}, I have a mission for you, here in the {class} district.  Listen closely, for there is no time to waste.", objectives = "Speak with Jennea Cannon in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1920] = { id = 1920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Blue Recluse", description = "A disturbance has been reported at the Blue Recluse tavern in the Mage Quarter.  Strange, invisible creatures now wander the tavern, and I fear a mana rift has formed there.\n\nI want you to investigate the tavern and capture those creatures.  Use the cantation of manifestation in the tavern to make the creatures visible, subdue them then use a containment coffer to capture them.  When you have enough, return to me with your filled coffers, your empty coffers and the cantation.", progress = "Have you captured the creatures, {name}?  They must be studied in order to determine the reason behind their arrival.", completion = "Very well done!  I will study these creatures and, with diligence and luck, determine how they slipped into our world.\n\nYour value to the society of mages grows, {name}.", objectives = "Obtain a Cantation of Manifestation and a Chest of Containment coffers from behind Jennea Cannon. Bring 3 Filled Containment Coffers to Jennea at the Wizard's Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1921] = { id = 1921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Materials", description = "You have served your fellow mages well, and now it is time to don your wizard's robe.  Wynne Larson can make your robe, but you must bring her the needed materials  \n\nThe robe will be made of linen which is easy to find, but you must also gain charged rift gems, and the only known location of the gems is in the Silver Stream Mine of Loch Modan, left in crates by the dwarven miners' league.\n\nGather the linen and the gems and bring them to Wynne Larson at the Larson Clothiers in the Mage District.", progress = "Hello, {name}.  Jennea told me you would come.  Do you have something for me?", completion = "Yes, these are great pieces of linen.  I can make a fine robe with them.  And after I weave the rift gems into it, we'll have a garment fit for a {class}!", objectives = "Bring 10 Linen and the 6 Charged Rift Gems to Wynne Larson in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1938] = { id = 1938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ur's Treatise on Shadow Magic", description = "Long ago, three mages studied in this tower until one fell to the dark arts.  He was urged to turn away from that evil magic, but he could not resist.  And so he was banished.\n\nThe fallen mage's new domain is the tower of Ilgalar in Redridge, and he took with him a powerful book--Ur's Treatise on Shadow Magic.\n\nWe, the mages of Stormwind, would have that book returned.  Enter the tower of Ilgalar, find the tome in his library, and bring it to me.", progress = "Do you have the book, {name}?  Its secrets are not meant for the untrained, and plumbing its depths can lead to doom and ruin.", completion = "I feared that Morganth had hidden the book elsewhere, or that he had found a way to open it and read its contents.\n\nIt is good to see that he did not, and that the seals we placed on Ur's Treatise on Shadow Magic still hold.", objectives = "Bring Ur's Treatise on Shadow Magic to High Sorcerer Andromath in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1939] = { id = 1939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Sorcerer Andromath", description = "High Sorcerer Andromath wishes to speak with you, {name}.  He is at the top of the wizard's sanctum, in the mage's district of Stormwind.\n\nIt would be wise to speak with him, for Andromath is one of the most powerful mages not locked away in Dalaran.  Council with him is high council indeed.", completion = "Greetings, {name}.  I am pleased to see you, and hope you have time to listen to an old man's words...", objectives = "Speak with High Sorcerer Andromath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1940] = { id = 1940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pristine Spider Silk", description = "Your service has been unwavering, {name}.  I think, perhaps, it is time you had a finer garment, one more suiting your station as an adept mage.  If you gather the needed materials, then we will arrange the robe made.\n\nYou must enter Duskwood and hunt carrion recluse spiders.  Extract their silk, but only the finest, most pristine silk will do.  When you have enough, take it to Wynne Larson, here in the mage district at the Larson Clothiers.  She will craft your robe.", progress = "Ah, yes.  The mages of the Wizard's Sanctum said you'd speak with me.  Do you have the required silk?", completion = "Nice specimens, these.  I'll get right to work!", objectives = "Bring 8 Pristine Spider Silk to Wynne Larson in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1941] = { id = 1941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaweave Robe", sourceObjective = "Here is your robe.  It's one of my best made yet!  Wear it with pride, and when people ask... tell them you got it at the Larson Clothiers!", sourceObjectiveStatus = "unverified-source-field" }
quests[1942] = { id = 1942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Astral Knot Garment", sourceObjective = "Your garment is ready!  And that silk you gathered was so nice... you don't mind if I made it a little short so that I'd have some silk left over for me, do you?\n\nI'm only joking.  It'll fit you great, and will be perfect for both adventure and formal dining.  Enjoy!", sourceObjectiveStatus = "unverified-source-field" }
quests[1943] = { id = 1943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Deino", description = "The troll mage Deino has need of your assistance, {name}.  She resides in Orgrimmar, in the Darkbriar Lodge.", completion = "Good, you have come.  My task is not an easy one, but vital to the society of mages.  If you aid me, I am sure you will find it worthwhile.", objectives = "Speak with Deino.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1944] = { id = 1944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waters of Xavian", description = "The fabled city of Xavian lies nestled deep within eastern Ashenvale, and tales of its ancient knowledge are well known among the learned.  It is said that the waters of Xavian hold vast magical powers.\n\nI would have a sample of those waters, from their source.\n\nTake this flask and go to Xavian.  Gather water from the bottom of its highest waterfall, and return to me.  And use care as you move through that ancient city--satyrs now hold the ruins and do not like mages prying into their affairs.", progress = "I am pleased you have returned with your skin intact, {name}.  Do you have the water sample?  I am eager to study its properties.", completion = "Ah, very good.  I trust the satyrs of Xavian gave you little trouble?\n\nThank you, {name}.  I will study this sample of Xavian water immediately.", objectives = "Bring the Xavian Water Sample to Deino in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1945] = { id = 1945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laughing Sisters", description = "For your services, I have arranged for the creation of your new robes, provided you can gather the needed materials...\n\nFor these robes, you must return to Ashenvale for the locks of hair from laughing sisters--dryads who gather near the Raynewood Retreat.\n\nWhen you have their hair, bring it to Kil'hala, a troll tailor at the Crossroads in the Barrens.  He will be expecting you, and will fashion your robes.", progress = "Greetings, {name}.  Deino said you would come, and would bring the laughing sisters' hair.  Do you have it?", completion = "Ah, this hair will weave into a fine robe, {name}.  It is a pity the laughing sisters had to die to part with it, though I do doubt they would ever give it willingly.\n\nA pity, but only a small one.", objectives = "Bring 12 Laughing Sister's Hairs to Kil'hala at the Crossroads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
